// Authored application questions. IDs remain stable for saved learning history.
// Each distractor represents a likely misconception rather than an unrelated joke.
export const assessmentTranslations = [];
const text = (en, ka, ru) => (assessmentTranslations.push([en, ka, ru]), en);
const bank = new Map();
const ask = (id, prompt, answers, correct, explanation) => bank.set(id, {id, type:'choice', prompt, answers, correct, explanation, assessmentVersion:2});

ask('first-engine-0',
  text('Combustion pushes a piston down. Which parts turn that movement into useful rotation?','წვა დგუშს ქვემოთ აწვება. რომელი ნაწილები გარდაქმნის ამ მოძრაობას სასარგებლო ბრუნვად?','Сгорание толкает поршень вниз. Какие детали превращают это движение во вращение?'), [
    text('Connecting rod and crankshaft','ბარბაცა და მუხლა ლილვი','Шатун и коленчатый вал'),
    text('Camshaft and intake valves','გამანაწილებელი ლილვი და შემშვები სარქველები','Распределительный вал и впускные клапаны'),
    text('Clutch and transmission gears','გადაბმულობა და კოლოფის კბილანები','Сцепление и шестерни коробки передач')],0,
  text('The rod transfers piston force to the offset crank journal. Valve gear controls breathing; the transmission receives rotation after the crankshaft produces it.','ბარბაცა დგუშის ძალას მუხლა ლილვის ექსცენტრულ ყელზე გადასცემს. სარქველები აირების მიმოცვლას მართავს; კოლოფი უკვე მიღებულ ბრუნვას იღებს.','Шатун передаёт усилие поршня на смещённую шатунную шейку. Клапанный механизм управляет газообменом, а коробка получает уже созданное вращение.'));
ask('first-engine-2',
  text('The engine stays near the same RPM while a different gear changes road speed. Which component makes this possible?','ძრავის ბრუნები თითქმის უცვლელია, სხვა გადაცემა კი გზის სიჩქარეს ცვლის. რომელი კვანძი იძლევა ამის საშუალებას?','Обороты двигателя почти одинаковы, но другая передача меняет скорость автомобиля. Какой узел это позволяет?'), [
    text('Transmission','ტრანსმისია','Трансмиссия'),text('Crankshaft','მუხლა ლილვი','Коленчатый вал'),text('Differential only','მხოლოდ დიფერენციალი','Только дифференциал')],0,
  text('Selecting a transmission ratio changes how many output revolutions correspond to one engine revolution. Engine RPM alone does not establish road speed.','კოლოფის გადაცემის არჩევა ცვლის ძრავის ერთ ბრუნზე გამომავალი ლილვის ბრუნების რაოდენობას. მხოლოდ ძრავის ბრუნები გზის სიჩქარეს ვერ განსაზღვრავს.','Выбор передаточного числа меняет количество оборотов на выходе на один оборот двигателя. По одним оборотам двигателя скорость автомобиля не определить.'));
ask('horsepower-0',
  text('Two engines do the same amount of mechanical work. Engine A takes half the time. How does its average power compare?','ორი ძრავა ერთნაირ მექანიკურ მუშაობას ასრულებს. A ძრავას ნახევარი დრო სჭირდება. როგორია მისი საშუალო სიმძლავრე?','Два двигателя выполняют одинаковую механическую работу. Двигатель A тратит вдвое меньше времени. Какова его средняя мощность?'), [
    text('Twice as much','ორჯერ მეტი','Вдвое больше'),text('The same','იგივე','Такая же'),text('Half as much','ნახევარი','Вдвое меньше')],0,
  text('Power is work divided by time. The same work in half the time requires twice the average power; torque alone does not express this rate.','სიმძლავრე მუშაობის დროის მიმართ შეფარდებაა. იგივე მუშაობა ნახევარ დროში ორმაგ საშუალო სიმძლავრეს მოითხოვს; მხოლოდ მომენტი ამ სიჩქარეს ვერ გამოხატავს.','Мощность — работа, делённая на время. Та же работа за половину времени означает удвоенную среднюю мощность; один крутящий момент эту скорость не описывает.'));
ask('horsepower-1',
  text('Engine A makes 300 Nm at 2,000 RPM. Engine B makes 300 Nm at 4,000 RPM. At these operating points, which makes more power?','A ძრავა 2 000 RPM-ზე 300 Nm-ს გამოიმუშავებს. B — 4 000 RPM-ზე 300 Nm-ს. ამ რეჟიმებში რომელს აქვს მეტი სიმძლავრე?','Двигатель A выдаёт 300 Nm при 2 000 RPM, B — 300 Nm при 4 000 RPM. В этих режимах у какого больше мощность?'), [
    text('B, twice the power of A','B-ს, A-ზე ორჯერ მეტი','У B, вдвое больше, чем у A'),text('Both have the same power','ორივეს ერთნაირი სიმძლავრე აქვს','У обоих одинаковая мощность'),text('A, twice the power of B','A-ს, B-ზე ორჯერ მეტი','У A, вдвое больше, чем у B')],0,
  text('Power depends on torque multiplied by rotational speed. Equal torque at twice the RPM means twice the power at that point, not necessarily twice the peak power.','სიმძლავრე დამოკიდებულია მომენტისა და ბრუნვის სიხშირის ნამრავლზე. იგივე მომენტი ორმაგ ბრუნებზე ამ რეჟიმში ორმაგ სიმძლავრეს ნიშნავს, თუმცა არა აუცილებლად ორმაგ პიკურ სიმძლავრეს.','Мощность зависит от произведения момента и частоты вращения. Тот же момент при удвоенных оборотах даёт двойную мощность в этой точке, но не обязательно двойную пиковую мощность.'));
ask('torque-0',
  text('A 20 N force acts perpendicular to a wrench, 0.5 m from the bolt. What torque does it produce?','ჭანჭიკიდან 0,5 მ მანძილზე გასაღებს მართობულად 20 N ძალა მოქმედებს. რა მომენტს ქმნის ის?','На ключ перпендикулярно действует сила 20 N на расстоянии 0,5 м от болта. Какой момент она создаёт?'),['10 Nm','20 Nm','40 Nm'],0,
  text('Torque = perpendicular force × lever arm: 20 × 0.5 = 10 Nm. Dividing force by the lever arm gives the wrong relationship.','მომენტი = მართობული ძალა × მხარი: 20 × 0,5 = 10 Nm. ძალის მხარზე გაყოფა არასწორ დამოკიდებულებას გვაძლევს.','Момент = перпендикулярная сила × плечо: 20 × 0,5 = 10 Nm. Деление силы на плечо даёт неверную зависимость.'));
ask('torque-1',
  text('The same perpendicular force is applied to a wrench twice as far from the bolt. What happens to torque?','იგივე მართობული ძალა გასაღებზე ჭანჭიკიდან ორჯერ შორს მოქმედებს. როგორ იცვლება მომენტი?','Та же перпендикулярная сила приложена к ключу вдвое дальше от болта. Как меняется момент?'),[
    text('It doubles','ორმაგდება','Удваивается'),text('It stays the same','უცვლელი რჩება','Не меняется'),text('It halves','ნახევრდება','Уменьшается вдвое')],0,
  text('Doubling the perpendicular lever arm doubles torque at the same force. Both force and distance from the axis matter.','იგივე ძალისას მართობული მხრის გაორმაგება მომენტსაც აორმაგებს. მნიშვნელობა ძალასაც აქვს და ღერძიდან მანძილსაც.','Удвоение перпендикулярного плеча при той же силе удваивает момент. Важны и сила, и расстояние до оси.'));
ask('torque-2',
  text('An ideal 2:1 reduction receives 100 Nm at 2,000 RPM. Which output pair is consistent?','იდეალურ 2:1 რედუქციას მიეწოდება 100 Nm 2 000 RPM-ზე. რომელი გამომავალი წყვილია სწორი?','На идеальное понижение 2:1 поступает 100 Nm при 2 000 RPM. Какая пара на выходе верна?'),[
    text('200 Nm at 1,000 RPM','200 Nm 1 000 RPM-ზე','200 Nm при 1 000 RPM'),text('200 Nm at 2,000 RPM','200 Nm 2 000 RPM-ზე','200 Nm при 2 000 RPM'),text('50 Nm at 1,000 RPM','50 Nm 1 000 RPM-ზე','50 Nm при 1 000 RPM')],0,
  text('The ratio doubles torque and halves speed. Doubling torque without reducing speed would create extra power; an ideal gearset cannot do that.','ეს გადაცემა მომენტს აორმაგებს და სიჩქარეს ანახევრებს. მომენტის სიჩქარის შემცირების გარეშე გაორმაგება დამატებით სიმძლავრეს შექმნიდა, რაც იდეალურ კბილანურ გადაცემას არ შეუძლია.','Передаточное число удваивает момент и вдвое снижает обороты. Удвоение момента без снижения оборотов создало бы дополнительную мощность, чего идеальная передача делать не может.'));
ask('rpm-0',
  text('An engine holds 3,000 RPM for 10 seconds. How many crankshaft revolutions occur?','ძრავა 10 წამის განმავლობაში 3 000 RPM-ზე მუშაობს. რამდენ ბრუნს ასრულებს მუხლა ლილვი?','Двигатель работает 10 секунд при 3 000 RPM. Сколько оборотов совершит коленчатый вал?'),['500','300','3,000'],0,
  text('Ten seconds is one sixth of a minute: 3,000 ÷ 6 = 500 revolutions. RPM is a per-minute rate, not the number of combustion events.','ათი წამი წუთის მეექვსედია: 3 000 ÷ 6 = 500 ბრუნი. RPM წუთში ბრუნვის სიხშირეა და არა წვის მოვლენების რაოდენობა.','Десять секунд — шестая часть минуты: 3 000 ÷ 6 = 500 оборотов. RPM — обороты в минуту, а не число воспламенений.'));
ask('rpm-1',
  text('A car holds the same road speed. Selecting a higher gear would normally make engine RPM…','ავტომობილი იმავე გზის სიჩქარეს ინარჩუნებს. უფრო მაღალ გადაცემაზე გადასვლა ძრავის ბრუნებს ჩვეულებრივ…','Автомобиль сохраняет скорость. Переход на более высокую передачу обычно…'),[
    text('Decrease','შეამცირებს','Снизит обороты двигателя'),text('Increase','გაზრდის','Повысит обороты двигателя'),text('Stay fixed by road speed alone','მხოლოდ გზის სიჩქარის გამო უცვლელს დატოვებს','Оставит обороты неизменными только из-за той же скорости')],0,
  text('A higher gear has less reduction, so the engine turns fewer times for the same wheel speed. This assumes the drive connection is engaged without slip.','მაღალ გადაცემას ნაკლები რედუქცია აქვს, ამიტომ თვლის იმავე სიჩქარეზე ძრავა ნაკლებ ბრუნს ასრულებს. აქ ამძრავი ჩართულია და სრიალი არ ხდება.','У более высокой передачи меньшее понижение: при тех же оборотах колёс двигатель вращается медленнее. Здесь предполагается включённая передача без проскальзывания.'));
ask('rpm-2',
  text('One cylinder of a four-stroke engine completes a cycle every two revolutions. At 2,000 RPM, how many cycles does it complete per minute?','ოთხტაქტიანი ძრავის ერთი ცილინდრი ციკლს ყოველ ორ ბრუნზე ასრულებს. 2 000 RPM-ზე რამდენ ციკლს ასრულებს ის წუთში?','Один цилиндр четырёхтактного двигателя завершает цикл за два оборота. Сколько циклов в минуту он совершает при 2 000 RPM?'),['1,000','2,000','4,000'],0,
  text('Divide crankshaft revolutions by two: 2,000 ÷ 2 = 1,000 cycles per minute for one cylinder. The four strokes are not four crankshaft revolutions.','მუხლა ლილვის ბრუნები გაყავი ორზე: 2 000 ÷ 2 = 1 000 ციკლი წუთში ერთი ცილინდრისთვის. ოთხი ტაქტი მუხლა ლილვის ოთხ ბრუნს არ ნიშნავს.','Делим обороты коленвала на два: 2 000 ÷ 2 = 1 000 циклов в минуту у одного цилиндра. Четыре такта — это не четыре оборота коленвала.'));
ask('charging-0',
  text('With a conventional combustion engine running, what is the alternator’s energy conversion?','ჩვეულებრივი შიდაწვის ძრავის მუშაობისას ენერგიის რა გარდაქმნას ასრულებს გენერატორი?','Как преобразует энергию генератор при работе обычного двигателя внутреннего сгорания?'),[
    text('Engine rotation into electrical power','ძრავის ბრუნვას ელექტრულ სიმძლავრედ','Вращение двигателя в электрическую мощность'),text('Stored electricity into starting rotation','შენახულ ელექტროენერგიას დაქოქვის ბრუნვად','Запасённую электроэнергию во вращение для запуска'),text('Electrical energy into a stored chemical reserve','ელექტროენერგიას შენახულ ქიმიურ მარაგად','Электроэнергию в химический запас')],0,
  text('The engine mechanically drives the alternator. The starter performs the opposite conversion during starting; the battery stores energy chemically.','ძრავა გენერატორს მექანიკურად ამოძრავებს. სტარტერი დაქოქვისას საპირისპირო გარდაქმნას ასრულებს; აკუმულატორი ენერგიას ქიმიურად ინახავს.','Двигатель механически приводит генератор. Стартер при запуске выполняет обратное преобразование, а аккумулятор хранит энергию химически.'));
ask('charging-2',
  text('A charging warning appears and the battery is low. Which conclusion follows from those facts alone?','ჩართულია დამუხტვის გაფრთხილება და აკუმულატორი დამჯდარია. მხოლოდ ამ ფაქტებიდან რა დასკვნა გამომდინარეობს?','Горит предупреждение о зарядке, аккумулятор разряжен. Какой вывод следует только из этих фактов?'),[
    text('The charging system needs checks of generation, drive and connections','დასატენ სისტემაში საჭიროა გამომუშავების, ამძრავისა და შეერთებების შემოწმება','Нужны проверки выработки тока, привода и соединений системы зарядки'),text('The alternator must be replaced','გენერატორი აუცილებლად შესაცვლელია','Генератор обязательно нужно заменить'),text('The battery alone must be replaced','მხოლოდ აკუმულატორია აუცილებლად შესაცვლელი','Обязательно нужно заменить только аккумулятор')],0,
  text('Low charge is an observation, not a component verdict. Belt drive, battery condition, wiring and alternator output can all matter.','დაბალი მუხტი დაკვირვებაა და არა კონკრეტული ნაწილის ბრალეულობის დადასტურება. მნიშვნელოვანია ღვედი, აკუმულატორის მდგომარეობა, გაყვანილობა და გენერატორის გამომუშავება.','Низкий заряд — наблюдение, а не приговор детали. Значение могут иметь ременной привод, состояние батареи, проводка и отдача генератора.'));
ask('differential-0',
  text('During a corner, the outside driven wheel travels farther in the same time. What must the differential allow?','მოსახვევში გარე წამყვანი თვალი იმავე დროში მეტ მანძილს გადის. რა უნდა დაუშვას დიფერენციალმა?','В повороте наружное ведущее колесо за то же время проходит больший путь. Что должен допускать дифференциал?'),[
    text('The outside wheel turns faster than the inside wheel','გარე თვალი შიდაზე სწრაფად ბრუნავს','Наружное колесо вращается быстрее внутреннего'),text('Both wheels are forced to turn at one speed','ორივე თვალი იძულებით ერთი სიჩქარით ბრუნავს','Оба колеса принудительно вращаются с одной скоростью'),text('The inside wheel turns faster than the outside wheel','შიდა თვალი გარეზე სწრაფად ბრუნავს','Внутреннее колесо вращается быстрее наружного')],0,
  text('A larger turning radius means a longer path. Different wheel speeds let both driven wheels follow their paths without requiring equal rotation.','უფრო დიდი მოხვევის რადიუსი გრძელ გზას ნიშნავს. სხვადასხვა ბრუნვის სიჩქარე ორივე წამყვან თვალს თავისი გზის გავლაში ეხმარება.','Больший радиус означает более длинный путь. Разные обороты позволяют обоим ведущим колёсам следовать своим траекториям без требования одинакового вращения.'));
ask('differential-2',
  text('Which comparison separates a transmission’s main job from a differential’s?','რომელი შედარება განასხვავებს კოლოფისა და დიფერენციალის მთავარ დანიშნულებებს?','Какое сравнение различает главные задачи коробки передач и дифференциала?'),[
    text('Selectable speed/torque ratios; different driven-wheel speeds','არჩევადი სიჩქარისა და მომენტის შეფარდებები; წამყვანი თვლების სხვადასხვა სიჩქარე','Выбираемые соотношения оборотов и момента; разные обороты ведущих колёс'),text('Different driven-wheel speeds; selectable engine ratios','წამყვანი თვლების სხვადასხვა სიჩქარე; ძრავის არჩევადი გადაცემები','Разные обороты ведущих колёс; выбираемые передачи двигателя'),text('Both mainly choose the engine’s operating temperature','ორივე ძირითადად ძრავის სამუშაო ტემპერატურას არჩევს','Оба главным образом задают рабочую температуру двигателя')],0,
  text('The transmission selects ratios between engine and drivetrain. The differential permits different speeds at its driven outputs; final-drive gearing can also reduce speed.','კოლოფი ძრავსა და ამძრავს შორის გადაცემას არჩევს. დიფერენციალი წამყვან გამოსასვლელებს განსხვავებულ სიჩქარეს აძლევს; მთავარი გადაცემაც ამცირებს ბრუნებს.','Коробка выбирает передаточное отношение между двигателем и приводом. Дифференциал допускает разные обороты приводимых выходов; главная передача также может понижать обороты.'));

ask('combustion-0',
  text('In the simplified four-stroke cycle, a piston rises with both valves closed. Which stroke is this?','გამარტივებულ ოთხტაქტიან ციკლში დგუში მაღლა მოძრაობს და ორივე სარქველი დახურულია. რომელი ტაქტია?','В упрощённом четырёхтактном цикле поршень идёт вверх при закрытых клапанах. Какой это такт?'),[
    text('Compression','შეკუმშვა','Сжатие'),text('Exhaust','გამოშვება','Выпуск'),text('Power','მუშა სვლა','Рабочий ход')],0,
  text('Compression traps the charge as the piston rises. Exhaust also moves upward, but needs an open exhaust valve; the power stroke moves downward.','შეკუმშვისას ჩაკეტილი მუხტი მაღლა მოძრავი დგუშით იკუმშება. გამოშვებისას დგუშიც მაღლა მიდის, მაგრამ გამოსაშვები სარქველი ღიაა; მუშა სვლა ქვემოთაა.','При сжатии запертый заряд сжимается поднимающимся поршнем. Выпуск тоже направлен вверх, но выпускной клапан открыт; рабочий ход направлен вниз.'));
ask('combustion-1',
  text('One cylinder completes 60 four-stroke cycles. How many crankshaft revolutions are required?','ერთი ცილინდრი 60 ოთხტაქტიან ციკლს ასრულებს. მუხლა ლილვის რამდენი ბრუნია საჭირო?','Один цилиндр завершает 60 четырёхтактных циклов. Сколько нужно оборотов коленвала?'),['120','60','240'],0,
  text('Each cycle takes two revolutions: 60 × 2 = 120. Count full cycles separately from individual piston strokes.','თითო ციკლს ორი ბრუნი სჭირდება: 60 × 2 = 120. სრული ციკლები დგუშის ცალკეული ტაქტებისგან განასხვავე.','На цикл нужны два оборота: 60 × 2 = 120. Полные циклы следует отличать от отдельных ходов поршня.'));
ask('combustion-2',
  text('What is the key ignition difference between normal petrol and diesel combustion?','რა მთავარი განსხვავებაა ჩვეულებრივი ბენზინისა და დიზელის ძრავების აალებას შორის?','В чём главное различие воспламенения в обычных бензиновом и дизельном двигателях?'),[
    text('Petrol uses a spark; diesel injects fuel into hot compressed air','ბენზინი ნაპერწკალს იყენებს; დიზელი საწვავს ცხელ შეკუმშულ ჰაერში აფრქვევს','Бензин воспламеняется искрой; дизель впрыскивает топливо в горячий сжатый воздух'),
    text('Both normally require an ignition spark for every cycle','ორივეს ჩვეულებრივ ყოველ ციკლზე აალების ნაპერწკალი სჭირდება','Обоим обычно нужна искра зажигания в каждом цикле'),
    text('Diesel compresses no air before fuel is injected','საწვავის შეფრქვევამდე დიზელი ჰაერს არ კუმშავს','Дизель не сжимает воздух перед впрыском топлива')],0,
  text('Compression heats diesel intake air enough for injected fuel to ignite. A petrol spark starts combustion in the charge; these are different ignition methods.','შეკუმშვა დიზელში ჰაერს საწვავის აალებისთვის საკმარისად აცხელებს. ბენზინის ძრავაში წვას ნაპერწკალი იწყებს; ეს აალების სხვადასხვა მეთოდია.','Сжатие нагревает воздух дизеля до воспламенения впрыснутого топлива. В бензиновом двигателе горение начинает искра; это разные способы воспламенения.'));
ask('turbocharging-0',
  text('Exhaust enters the turbine. How does that energy reach the fresh intake air?','გამონაბოლქვი ტურბინაში შედის. როგორ გადადის ეს ენერგია სუფთა შემშვებ ჰაერზე?','Выхлоп поступает в турбину. Как его энергия передаётся свежему впускному воздуху?'),[
    text('A shaft drives a separate compressor','ლილვი ცალკე კომპრესორს ამოძრავებს','Вал приводит отдельный компрессор'),text('Exhaust mixes directly with fresh air inside the turbo','ტურბოში გამონაბოლქვი პირდაპირ ერევა სუფთა ჰაერს','Выхлоп напрямую смешивается со свежим воздухом внутри турбины'),text('The turbine cools the intake air before compressing it','ტურბინა შეკუმშვამდე შემშვებ ჰაერს აგრილებს','Турбина охлаждает впускной воздух перед сжатием')],0,
  text('The shared shaft transfers mechanical power. Intake air and exhaust use separate flow paths; the charge-air cooler removes heat after compression.','საერთო ლილვი მექანიკურ სიმძლავრეს გადასცემს. ჰაერსა და გამონაბოლქვს ცალკე არხები აქვს; შეკუმშვის შემდეგ სითბოს ინტერკულერი აშორებს.','Общий вал передаёт механическую мощность. Впуск и выхлоп идут по разным каналам; охладитель наддува отводит тепло после сжатия.'));
ask('turbocharging-1',
  text('Which change explains why a charge-air cooler is placed after the compressor?','რომელი ცვლილება ხსნის, რატომ დგას ინტერკულერი კომპრესორის შემდეგ?','Какое изменение объясняет установку охладителя наддува после компрессора?'),[
    text('Compression raises intake-air temperature','შეკუმშვა შემშვები ჰაერის ტემპერატურას ზრდის','Сжатие повышает температуру впускного воздуха'),text('Compression turns the intake air into exhaust gas','შეკუმშვა შემშვებ ჰაერს გამონაბოლქვად აქცევს','Сжатие превращает впускной воздух в выхлоп'),text('The cooler supplies mechanical drive to the turbo shaft','ინტერკულერი ტურბოს ლილვს მექანიკურად ამოძრავებს','Охладитель механически приводит вал турбины')],0,
  text('Compressing air adds heat. The cooler removes some of it before the cylinders; it neither mixes the gas streams nor drives the shaft.','შეკუმშვა ჰაერს აცხელებს. ცილინდრებამდე ინტერკულერი სითბოს ნაწილს აშორებს; ის არც აირებს ურევს და არც ლილვს ამოძრავებს.','Сжатие нагревает воздух. Охладитель отводит часть тепла перед цилиндрами; он не смешивает потоки и не приводит вал.'));
ask('turbocharging-2',
  text('A specification says “one twin-scroll turbocharger.” Which interpretation is correct?','სპეციფიკაციაში წერია „ერთი twin-scroll ტურბო“. რომელი განმარტებაა სწორი?','В спецификации указан «один турбокомпрессор twin-scroll». Как это понимать?'),[
    text('One turbo unit with separated turbine-inlet passages','ერთი ტურბო ტურბინის ცალკე შემშვები არხებით','Один агрегат с раздельными входными каналами турбины'),text('Two turbo units sharing one compressor','ორი ტურბო ერთი საერთო კომპრესორით','Два агрегата с общим компрессором'),text('One turbo for intake and another for exhaust','ერთი ტურბო შემშვები და მეორე გამოსაშვები სისტემისთვის','Одна турбина для впуска и другая для выпуска')],0,
  text('Twin-scroll describes the turbine inlet, not the number of turbo units. A single turbo already includes both turbine and compressor sides.','Twin-scroll ტურბინის შესასვლელს აღწერს და არა ტურბოების რაოდენობას. ერთ ტურბოსაც აქვს ტურბინისა და კომპრესორის მხარეები.','Twin-scroll описывает вход турбины, а не число агрегатов. У одного турбокомпрессора уже есть турбинная и компрессорная стороны.'));
ask('transmission-0',
  text('At the same engine torque, which ideal reduction gives more output torque for a low-speed climb?','ძრავის იმავე მომენტზე რომელი იდეალური რედუქცია იძლევა მეტ გამომავალ მომენტს დაბალ სიჩქარეზე ასასვლელად?','При одинаковом моменте двигателя какое идеальное понижение даст больше момента на выходе для медленного подъёма?'),['3:1','2:1','1:1'],0,
  text('The 3:1 reduction multiplies input torque by three, trading output speed for torque. It does not add engine power.','3:1 რედუქცია შემავალ მომენტს სამზე ამრავლებს და გამომავალ სიჩქარეს ამცირებს. ძრავის სიმძლავრეს ის არ ამატებს.','Понижение 3:1 утраивает входной момент, обменивая обороты на момент. Мощность двигателя оно не увеличивает.'));
ask('transmission-1',
  text('A 3:1 gearbox reduction is followed by a 4:1 final drive. At 2,400 engine RPM, what is ideal wheel speed?','3:1 კოლოფის რედუქციას 4:1 მთავარი გადაცემა მოჰყვება. ძრავის 2 400 RPM-ზე რამდენია თვლის იდეალური ბრუნები?','За понижением коробки 3:1 следует главная передача 4:1. Каковы идеальные обороты колёс при 2 400 RPM двигателя?'),['200 RPM','600 RPM','800 RPM'],0,
  text('Multiply reductions: 3 × 4 = 12. Then divide: 2,400 ÷ 12 = 200 RPM. Ignoring the final drive gives 800 RPM at the gearbox output, not the wheel.','რედუქციები გაამრავლე: 3 × 4 = 12. შემდეგ გაყავი: 2 400 ÷ 12 = 200 RPM. მთავარი გადაცემის გამოტოვებით მიღებული 800 RPM კოლოფის გამოსასვლელია და არა თვალი.','Умножаем понижения: 3 × 4 = 12. Делим: 2 400 ÷ 12 = 200 RPM. Без главной передачи получится 800 RPM на выходе коробки, а не на колесе.'));
ask('transmission-2',
  text('A torque converter’s lock-up clutch engages during suitable driving conditions. What loss is it intended to reduce?','შესაფერის რეჟიმში ჰიდროტრანსფორმატორის ბლოკირების გადაბმულობა ირთვება. რომელი დანაკარგის შემცირებას ემსახურება ის?','В подходящем режиме включается блокировка гидротрансформатора. Какие потери она уменьшает?'),[
    text('Slip between converter input and output','სრიალს ჰიდროტრანსფორმატორის შესასვლელსა და გამოსასვლელს შორის','Проскальзывание между входом и выходом гидротрансформатора'),text('All friction inside the gearbox','კოლოფში არსებულ მთელ ხახუნს','Всё трение внутри коробки'),text('The final drive’s speed reduction','მთავარი გადაცემის რედუქციას','Понижение оборотов главной передачей')],0,
  text('Lock-up establishes a mechanical connection across the converter. Gear ratios and other transmission losses still exist.','ბლოკირება ჰიდროტრანსფორმატორის შესასვლელსა და გამოსასვლელს მექანიკურად აკავშირებს. გადაცემათა შეფარდებები და სხვა დანაკარგები მაინც არსებობს.','Блокировка создаёт механическую связь между входом и выходом гидротрансформатора. Передаточные числа и другие потери в трансмиссии сохраняются.'));
ask('engine-codes-0',
  text('Which documented pair correctly separates the N54 from the N55 examples in this lesson?','რომელი დოკუმენტირებული წყვილი განასხვავებს ამ გაკვეთილის N54 და N55 მაგალითებს სწორად?','Какая документированная пара верно различает примеры N54 и N55 из урока?'),[
    text('N54: two turbos; N55: one twin-scroll turbo','N54: ორი ტურბო; N55: ერთი twin-scroll ტურბო','N54: две турбины; N55: одна twin-scroll'),text('N54: one turbo; N55: two turbos','N54: ერთი ტურბო; N55: ორი ტურბო','N54: одна турбина; N55: две турбины'),text('Both use two turbos because both are inline sixes','ორივეს ორი ტურბო აქვს, რადგან ორივე რიგითი ექვსცილინდრიანია','У обоих две турбины, потому что оба рядные шестёрки')],0,
  text('BMW documents twin turbos for the 335is N54 and a single twin-scroll unit for the 2011 135i N55. Cylinder count does not establish turbo count.','BMW 335is-ის N54-ისთვის ორ ტურბოს, ხოლო 2011 წლის 135i-ის N55-ისთვის ერთ twin-scroll ტურბოს ასახელებს. ცილინდრების რაოდენობა ტურბოების რაოდენობას არ განსაზღვრავს.','BMW указывает две турбины у N54 модели 335is и одну twin-scroll у N55 модели 135i 2011 года. Число цилиндров не определяет число турбин.'));
ask('engine-codes-1',
  text('Two listings both say “B58.” What is still needed before comparing their exact hardware?','ორ განცხადებაში წერია „B58“. რა არის კიდევ საჭირო მათი ზუსტი მოწყობილობის შესადარებლად?','В двух объявлениях указано «B58». Что ещё нужно для сравнения точного оборудования?'),[
    text('Full variant, production details and documented application','სრული მოდიფიკაცია, წარმოების მონაცემები და დოკუმენტირებული გამოყენება','Полная модификация, данные производства и документированное применение'),text('Only the shared family code','მხოლოდ საერთო ოჯახის კოდი','Только общий код семейства'),text('Only the cars’ exterior model badges','მხოლოდ ავტომობილების გარე მოდელის ნიშნები','Только наружные обозначения моделей')],0,
  text('A family code groups related engines. Revisions and vehicle installations can differ, so the code alone does not establish identical hardware.','ოჯახის კოდი მონათესავე ძრავებს აჯგუფებს. რევიზიები და ავტომობილში განლაგება შეიძლება განსხვავდებოდეს, ამიტომ მარტო კოდი იდენტურ მოწყობილობას ვერ ადასტურებს.','Код семейства объединяет родственные двигатели. Ревизии и установки в автомобили могут отличаться, поэтому код не доказывает идентичность оборудования.'));
ask('engine-codes-2',
  text('A part is advertised for an N55. Which evidence best supports fitting it to a particular car?','ნაწილი N55-ისთვის იყიდება. რომელი მტკიცებულება ადასტურებს მის კონკრეტულ ავტომობილთან თავსებადობას უკეთ?','Деталь продаётся для N55. Какое доказательство лучше подтверждает её совместимость с конкретным автомобилем?'),[
    text('A matching application and part reference for that vehicle variant','ამ ავტომობილის მოდიფიკაციის შესაბამისი გამოყენება და ნაწილის ნომერი','Совпадающие применение и номер детали для этой модификации'),text('A similar shape in an online photograph','ინტერნეტფოტოზე მსგავსი ფორმა','Похожая форма на фотографии в интернете'),text('The same engine-family name on the listing','განცხადებაში იგივე ძრავის ოჯახის სახელი','То же название семейства двигателя в объявлении')],0,
  text('Match the documented application, not only the family or appearance. Packaging, connections and revisions may differ within one engine family.','შეადარე დოკუმენტირებული გამოყენება და არა მხოლოდ ოჯახი ან გარეგნობა. ერთი ოჯახის შიგნით განლაგება, შეერთებები და რევიზიები შეიძლება განსხვავდებოდეს.','Сверяйте документированное применение, а не только семейство или вид. Компоновка, соединения и ревизии внутри семейства могут отличаться.'));
ask('cooling-0',
  text('Coolant circulates normally, but there is very little airflow through the radiator. Which transfer is most directly reduced?','გამაგრილებელი სითხე ნორმალურად მოძრაობს, მაგრამ რადიატორში ჰაერი თითქმის არ გადის. რომელი გადაცემა მცირდება უშუალოდ?','Охлаждающая жидкость циркулирует нормально, но через радиатор почти не идёт воздух. Какая передача непосредственно уменьшается?'),[
    text('Heat from coolant to surrounding air','სითბო გამაგრილებელი სითხიდან გარემოს ჰაერში','Тепло от жидкости к окружающему воздуху'),text('Mechanical drive from pump to crankshaft','მექანიკური ამძრავი ტუმბოდან მუხლა ლილვზე','Механический привод от помпы к коленвалу'),text('Intake pressure from compressor to cylinders','შემშვები წნევა კომპრესორიდან ცილინდრებამდე','Давление впуска от компрессора к цилиндрам')],0,
  text('The radiator needs air as well as circulating coolant. Coolant flow alone does not guarantee that heat can leave the system effectively.','რადიატორს მოძრავ სითხესთან ერთად ჰაერიც სჭირდება. მხოლოდ სითხის მოძრაობა სისტემიდან სითბოს ეფექტურ მოცილებას ვერ უზრუნველყოფს.','Радиатору нужен и воздух, и циркулирующая жидкость. Одна циркуляция не гарантирует эффективный отвод тепла из системы.'));
ask('cooling-1',
  text('A cold engine routes coolant through a bypass while limiting radiator flow. What is the intended result?','ცივი ძრავა სითხეს შემოვლით არხში ატარებს და რადიატორში ნაკადს ზღუდავს. რა არის მიზანი?','Холодный двигатель направляет жидкость по байпасу, ограничивая поток через радиатор. Какова цель?'),[
    text('Warm up while maintaining circulation','ცირკულაციის შენარჩუნებით გათბობა','Прогрев с сохранением циркуляции'),text('Stop all coolant movement until hot','გაცხელებამდე სითხის მოძრაობის სრულად შეჩერება','Полная остановка жидкости до прогрева'),text('Reject maximum heat immediately','სითბოს დაუყოვნებლივ მაქსიმალური მოცილება','Немедленный максимальный отвод тепла')],0,
  text('Limiting radiator heat loss helps warm-up. The bypass still permits circulation; a closed radiator route is not the same as a stopped pump.','რადიატორში სითბოს დაკარგვის შეზღუდვა გათბობას ეხმარება. შემოვლითი არხი ცირკულაციას ინარჩუნებს; რადიატორის დახურული გზა გაჩერებულ ტუმბოს არ ნიშნავს.','Ограничение потерь тепла через радиатор помогает прогреву. Байпас сохраняет циркуляцию; закрытый путь к радиатору не означает остановку помпы.'));
ask('cooling-2',
  text('A diagram labels both an engine radiator and a charge-air cooler. Which distinction is correct?','სქემაზე მითითებულია ძრავის რადიატორი და ინტერკულერი. რომელი განსხვავებაა სწორი?','На схеме есть радиатор двигателя и охладитель наддува. Какое различие верно?'),[
    text('They remove heat from different working streams','ისინი სხვადასხვა სამუშაო ნაკადს სითბოს აშორებს','Они отводят тепло от разных рабочих потоков'),text('They always share one coolant circuit','მათ ყოველთვის ერთი საერთო სითხის წრედი აქვს','У них всегда один общий жидкостный контур'),text('Only the radiator is a heat exchanger','თბომცვლელი მხოლოდ რადიატორია','Только радиатор является теплообменником')],0,
  text('One manages engine-coolant heat; the other cools compressed intake air. Charge cooling can use air or a liquid circuit, so names alone do not establish shared plumbing.','ერთი ძრავის სითხის სითბოს მართავს, მეორე შეკუმშულ შემშვებ ჰაერს აგრილებს. ინტერკულერი ჰაერს ან სითხის წრედს იყენებს, ამიტომ სახელებით საერთო მილები ვერ დგინდება.','Один отводит тепло охлаждающей жидкости двигателя, другой охлаждает сжатый впускной воздух. Наддув охлаждают воздухом или жидкостным контуром; названия не доказывают общие трубопроводы.'));
ask('suspension-0',
  text('After one simulated bump, the body keeps oscillating. Which component’s main role is to resist that repeated motion?','სიმულაციაში ერთი ბიძგის შემდეგ ძარა რხევას აგრძელებს. რომელი ნაწილის მთავარი როლია განმეორებადი მოძრაობის წინააღმდეგობა?','После одной неровности в симуляции кузов продолжает раскачиваться. Какой компонент прежде всего сопротивляется повторным колебаниям?'),[
    text('Damper','ამორტიზატორი','Амортизатор'),text('Spring','ზამბარა','Пружина'),text('Anti-roll bar alone','მხოლოდ განივი მდგრადობის სტაბილიზატორი','Только стабилизатор поперечной устойчивости')],0,
  text('A spring stores and releases energy. Damping dissipates motion energy, helping oscillations settle; this observation alone still does not identify a real vehicle fault.','ზამბარა ენერგიას ინახავს და აბრუნებს. ამორტიზაცია მოძრაობის ენერგიას ფანტავს და რხევის ჩაქრობას ეხმარება; მარტო ეს დაკვირვება რეალურ გაუმართაობას ვერ ადგენს.','Пружина запасает и отдаёт энергию. Демпфирование рассеивает энергию движения и гасит колебания; одно наблюдение ещё не устанавливает неисправность реального автомобиля.'));
ask('suspension-1',
  text('A hydraulic damper resists repeated motion. Where does much of that dissipated motion energy go?','ჰიდრავლიკური ამორტიზატორი განმეორებად მოძრაობას ეწინააღმდეგება. სად მიდის გაფანტული მოძრაობის ენერგიის დიდი ნაწილი?','Гидравлический амортизатор сопротивляется колебаниям. Куда уходит значительная часть рассеянной энергии движения?'),[
    text('Into heat in the damper','ამორტიზატორში სითბოდ','В тепло в амортизаторе'),text('Back into the spring with no losses','უდანაკარგოდ უკან ზამბარაში','Обратно в пружину без потерь'),text('Into permanently greater spring stiffness','ზამბარის მუდმივად გაზრდილ სიხისტედ','В постоянно увеличенную жёсткость пружины')],0,
  text('Fluid resistance dissipates mechanical energy as heat. Damping is different from storing energy in a spring or changing the spring rate.','სითხის წინააღმდეგობა მექანიკურ ენერგიას სითბოდ ფანტავს. ამორტიზაცია განსხვავდება ზამბარაში ენერგიის შენახვისა და მისი სიხისტის ცვლილებისგან.','Сопротивление жидкости рассеивает механическую энергию в тепло. Демпфирование отличается от накопления энергии в пружине и изменения её жёсткости.'));
ask('suspension-2',
  text('An adaptive damper switches to a firmer setting. What does it primarily change?','ადაპტიური ამორტიზატორი უფრო მყარ რეჟიმზე გადადის. რას ცვლის ის ძირითადად?','Адаптивный амортизатор переходит в более жёсткий режим. Что прежде всего меняется?'),[
    text('Resistance to suspension movement','საკიდრის მოძრაობის წინააღმდეგობა','Сопротивление движению подвески'),text('The spring’s material stiffness','ზამბარის მასალის სიხისტე','Жёсткость материала пружины'),text('The suspension’s maximum travel by itself','თავისთავად საკიდრის მაქსიმალური სვლა','Сам по себе максимальный ход подвески')],0,
  text('Adaptive damping varies motion resistance. A firmer damping setting is not automatically more grip; the tire must still follow the road.','ადაპტიური ამორტიზაცია მოძრაობის წინააღმდეგობას ცვლის. უფრო მკაცრი რეჟიმი ავტომატურად უკეთეს მოჭიდებას არ ნიშნავს; საბურავი გზას უნდა მიჰყვებოდეს.','Адаптивное демпфирование меняет сопротивление движению. Более жёсткий режим не означает автоматически лучшее сцепление: колесо должно следовать дороге.'));
ask('electronics-0',
  text('Which pair correctly separates measurement from action in stability control?','რომელი წყვილი განასხვავებს სტაბილურობის მართვაში გაზომვასა და მოქმედებას სწორად?','Какая пара верно различает измерение и действие в системе стабилизации?'),[
    text('Wheel-speed sensor measures; brake actuator applies force','თვლის სიჩქარის სენსორი ზომავს; სამუხრუჭე მექანიზმი ძალას ქმნის','Датчик скорости колеса измеряет; тормозной исполнительный механизм создаёт усилие'),text('Brake actuator measures; wheel-speed sensor applies force','სამუხრუჭე მექანიზმი ზომავს; თვლის სიჩქარის სენსორი ძალას ქმნის','Тормозной механизм измеряет; датчик скорости колеса создаёт усилие'),text('Both only store the controller’s instructions','ორივე მხოლოდ კონტროლერის ბრძანებებს ინახავს','Оба только хранят команды контроллера')],0,
  text('Sensors provide evidence about physical conditions. Actuators change the system; the controller chooses commands using the measurements.','სენსორები ფიზიკური მდგომარეობის შესახებ მონაცემებს იძლევა. შემსრულებელი მექანიზმები სისტემას ცვლის; კონტროლერი ბრძანებებს გაზომვებით არჩევს.','Датчики сообщают о физических условиях. Исполнительные устройства изменяют систему, а контроллер выбирает команды по измерениям.'));
ask('electronics-1',
  text('The controller reduces drive torque, then reads vehicle motion again. Why take another measurement?','კონტროლერი ამძრავის მომენტს ამცირებს და მოძრაობას ხელახლა ზომავს. რატომ არის ახალი გაზომვა საჭირო?','Контроллер уменьшает тяговый момент, затем снова измеряет движение. Зачем повторное измерение?'),[
    text('To check the response and adjust the next command','რეაქციის შესამოწმებლად და შემდეგი ბრძანების შესასწორებლად','Чтобы проверить результат и скорректировать следующую команду'),text('To prove the first command must have worked','იმის დასამტკიცებლად, რომ პირველი ბრძანება აუცილებლად იმუშავებდა','Чтобы доказать, что первая команда обязательно сработала'),text('To replace the need for any driver-intent signal','მძღოლის განზრახვის ნებისმიერი სიგნალის შესაცვლელად','Чтобы заменить любой сигнал о намерении водителя')],0,
  text('Feedback closes the loop: measure, compare, act, then measure again. A command alone does not confirm the physical result.','უკუკავშირი წრედს კრავს: გაზომე, შეადარე, იმოქმედე და კვლავ გაზომე. მარტო ბრძანება ფიზიკურ შედეგს ვერ ადასტურებს.','Обратная связь замыкает контур: измерить, сравнить, воздействовать и измерить снова. Команда сама по себе не подтверждает физический результат.'));
ask('electronics-2',
  text('One wheel-speed signal drops out while the others stay plausible. What is the strongest conclusion so far?','ერთი თვლის სიჩქარის სიგნალი ქრება, დანარჩენები კი სარწმუნოა. ამ ეტაპზე რა დასკვნაა ყველაზე დასაბუთებული?','Сигнал скорости одного колеса пропадает, остальные правдоподобны. Какой вывод пока наиболее обоснован?'),[
    text('That signal path needs investigation','ამ სიგნალის გზას გამოკვლევა სჭირდება','Этот сигнальный тракт требует проверки'),text('The named sensor is definitely faulty','დასახელებული სენსორი აუცილებლად გაფუჭებულია','Названный датчик точно неисправен'),text('The controller is definitely faulty','კონტროლერი აუცილებლად გაფუჭებულია','Контроллер точно неисправен')],0,
  text('The evidence localizes an implausible signal, not a failed component. Sensor, supply, connector, wiring and processing remain possible causes.','მტკიცებულება არასარწმუნო სიგნალს გამოავლენს და არა კონკრეტულ დაზიანებულ ნაწილს. სენსორი, კვება, შეერთება, გაყვანილობა და დამუშავება კვლავ შესაძლო მიზეზებია.','Данные указывают на неправдоподобный сигнал, а не на конкретную сломанную деталь. Возможны датчик, питание, разъём, проводка и обработка.'));
ask('electrification-0',
  text('A car has a combustion engine, electric drive and a battery that accepts external charging. Which category fits?','ავტომობილს აქვს შიდაწვის ძრავა, ელექტროამძრავი და გარედან დამუხტვადი აკუმულატორი. რომელ კატეგორიას ეკუთვნის?','У автомобиля есть ДВС, электротяга и батарея с внешней зарядкой. Какая это категория?'),[
    text('Plug-in hybrid','დასამუხტი ჰიბრიდი','Подключаемый гибрид'),text('Conventional hybrid without a plug','ჩვეულებრივი ჰიბრიდი დამტენის გარეშე','Обычный гибрид без внешней зарядки'),text('Battery-electric vehicle','სრულად ელექტროავტომობილი','Аккумуляторный электромобиль')],0,
  text('External charging plus combustion and electric drive describes a plug-in hybrid. A battery-electric vehicle has no combustion propulsion engine.','გარედან დამუხტვა, შიდაწვისა და ელექტროამძრავი დასამუხტ ჰიბრიდს აღწერს. სრულ ელექტროავტომობილს ამძრავი შიდაწვის ძრავა არ აქვს.','Внешняя зарядка вместе с ДВС и электротягой описывает подключаемый гибрид. У электромобиля нет тягового двигателя внутреннего сгорания.'));
ask('electrification-1',
  text('During regenerative deceleration, which energy path is correct?','რეკუპერაციული შენელებისას ენერგიის რომელი გზაა სწორი?','Каков верный путь энергии при рекуперативном замедлении?'),[
    text('Vehicle motion → motor/generator → battery','ავტომობილის მოძრაობა → ძრავა/გენერატორი → აკუმულატორი','Движение автомобиля → мотор-генератор → батарея'),text('Battery → motor → vehicle motion','აკუმულატორი → ძრავა → ავტომობილის მოძრაობა','Батарея → мотор → движение автомобиля'),text('Friction-brake heat → battery with no losses','ხახუნის მუხრუჭის სითბო → აკუმულატორი უდანაკარგოდ','Тепло фрикционных тормозов → батарея без потерь')],0,
  text('The motor acts as a generator and recovers some motion energy electrically. The opposite direction is propulsion; heat already lost in friction brakes is not fully recovered.','ძრავა გენერატორად მუშაობს და მოძრაობის ენერგიის ნაწილს ელექტრულად აბრუნებს. საპირისპირო გზა ამძრავია; ხახუნის მუხრუჭში დაკარგული სითბო სრულად არ ბრუნდება.','Мотор работает генератором и возвращает часть энергии движения электрически. Обратное направление — тяга; тепло, уже рассеянное тормозами, полностью не возвращается.'));
ask('electrification-2',
  text('The battery is nearly full and regeneration is limited. What still provides the required braking?','აკუმულატორი თითქმის სავსეა და რეკუპერაცია შეზღუდულია. რა უზრუნველყოფს კვლავ საჭირო დამუხრუჭებას?','Батарея почти полная, рекуперация ограничена. Что по-прежнему обеспечивает требуемое торможение?'),[
    text('Friction brakes','ხახუნის მუხრუჭები','Фрикционные тормоза'),text('Unlimited charging into the full battery','სავსე აკუმულატორის შეუზღუდავი დატენვა','Неограниченная зарядка полной батареи'),text('The accelerator pedal alone','მხოლოდ აქსელერატორის პედალი','Только педаль акселератора')],0,
  text('The battery cannot always accept the requested energy. Friction brakes remain necessary when regeneration is insufficient or unavailable.','აკუმულატორი ყოველთვის ვერ იღებს მოთხოვნილ ენერგიას. ხახუნის მუხრუჭები საჭიროა, როცა რეკუპერაცია არასაკმარისია ან მიუწვდომელია.','Батарея не всегда может принять нужную энергию. Фрикционные тормоза необходимы при недостаточной или недоступной рекуперации.'));

ask('part-turbocharger-function',
  text('Which pair belongs on the turbo’s two separate gas paths?','რომელი წყვილი ეკუთვნის ტურბოს ორ ცალკე აირის გზას?','Какая пара относится к двум отдельным газовым трактам турбокомпрессора?'),[
    text('Exhaust to turbine; filtered air to compressor','გამონაბოლქვი ტურბინაში; გაფილტრული ჰაერი კომპრესორში','Выхлоп к турбине; очищенный воздух к компрессору'),text('Filtered air to turbine; exhaust to compressor','გაფილტრული ჰაერი ტურბინაში; გამონაბოლქვი კომპრესორში','Очищенный воздух к турбине; выхлоп к компрессору'),text('Exhaust and filtered air mix before the compressor','გამონაბოლქვი და გაფილტრული ჰაერი კომპრესორამდე ირევა','Выхлоп и очищенный воздух смешиваются перед компрессором')],0,
  text('The turbine extracts exhaust energy; its shaft drives the intake compressor. Shared rotation does not mean shared gas flow.','ტურბინა გამონაბოლქვის ენერგიას იღებს და ლილვით შემშვებ კომპრესორს ამოძრავებს. საერთო ბრუნვა საერთო აირის ნაკადს არ ნიშნავს.','Турбина получает энергию выхлопа и валом приводит впускной компрессор. Общее вращение не означает общий поток газа.'));
ask('part-turbocharger-symptom',
  text('Boost is low and a charge hose has a visible open split. What does that extra evidence support?','ბუსტი დაბალია და შეკუმშული ჰაერის შლანგს ღია ბზარი ეტყობა. რას ამყარებს ეს დამატებითი მტკიცებულება?','Наддув низкий, на патрубке виден открытый разрыв. Что подтверждает эта дополнительная улика?'),[
    text('A leak in the compressed-air path','შეკუმშული ჰაერის გზის გაჟონვას','Утечку в тракте сжатого воздуха'),text('Certain turbine-wheel damage','ტურბინის ფრთის უცილობელ დაზიანებას','Несомненное повреждение турбинного колеса'),text('Proof that the boost sensor alone is wrong','მტკიცებას, რომ მხოლოდ ბუსტის სენსორი ცდება','Доказательство ошибки только датчика наддува')],0,
  text('A split downstream of the compressor lets pressurized air escape. Low boost alone has several causes; the visible leak adds specific evidence.','კომპრესორის შემდეგ ბზარი წნევიან ჰაერს გარეთ უშვებს. დაბალ ბუსტს რამდენიმე მიზეზი აქვს; ხილული გაჟონვა კონკრეტულ მტკიცებულებას ამატებს.','Разрыв после компрессора выпускает сжатый воздух. У низкого наддува несколько причин; видимая утечка добавляет конкретное доказательство.'));
ask('part-air-filter-function',
  text('A filter element is clean, but its perimeter seal leaves a gap. Why can this still be a problem?','ფილტრი სუფთაა, მაგრამ პერიმეტრის დალუქვაში ღრიჭო რჩება. რატომ არის ეს მაინც პრობლემა?','Фильтрующий элемент чистый, но по краю уплотнения есть зазор. Почему это всё равно проблема?'),[
    text('Air can bypass the filtering material','ჰაერს შეუძლია ფილტრის მასალას გვერდი აუაროს','Воздух может обойти фильтрующий материал'),text('The filter automatically becomes more restrictive','ფილტრი ავტომატურად უფრო დიდ წინააღმდეგობას ქმნის','Фильтр автоматически создаёт большее сопротивление'),text('The gap filters smaller particles than the pleats','ღრიჭო ნაკეცებზე უფრო პატარა ნაწილაკებს ფილტრავს','Зазор фильтрует частицы мельче складок')],0,
  text('Filtration needs a sealed path through the media. A good element cannot trap dirt in air that travels around its edge.','ფილტრაციას მასალაში დალუქული გზა სჭირდება. კარგი ელემენტიც ვერ დაიჭერს ჭუჭყს იმ ჰაერში, რომელიც კიდეს უვლის.','Для фильтрации нужен герметичный путь через материал. Даже хороший элемент не задержит грязь в воздухе, обходящем его по краю.'));
ask('part-air-filter-symptom',
  text('Which observation most directly supports a restriction at the engine air filter?','რომელი დაკვირვება ამყარებს უშუალოდ ძრავის ჰაერის ფილტრის შეზღუდვას?','Какое наблюдение наиболее прямо указывает на ограничение в воздушном фильтре двигателя?'),[
    text('A heavily blocked filter element in the intake path','შემშვებ გზაში ძლიერ დახშული ფილტრი','Сильно забитый элемент во впускном тракте'),text('A damaged cabin pollen filter','დაზიანებული სალონის ფილტრი','Повреждённый салонный фильтр'),text('A charging warning with a clean intake filter','დამუხტვის გაფრთხილება სუფთა შემშვები ფილტრით','Предупреждение о зарядке при чистом впускном фильтре')],0,
  text('The engine filter is in the combustion-air path. A cabin filter cleans passenger air, and a charging warning concerns another system.','ძრავის ფილტრი წვისთვის განკუთვნილი ჰაერის გზაშია. სალონის ფილტრი მგზავრების ჰაერს წმენდს, დამუხტვის გაფრთხილება კი სხვა სისტემას ეხება.','Фильтр двигателя стоит на пути воздуха для сгорания. Салонный очищает воздух пассажиров, а предупреждение о зарядке относится к другой системе.'));
ask('part-spark-plug-function',
  text('What crosses the spark plug’s electrode gap to start petrol combustion?','რა გადადის სანთლის ელექტროდებს შორის ბენზინის წვის დასაწყებად?','Что проходит через зазор электродов свечи для начала сгорания бензина?'),[
    text('A high-voltage electrical discharge','მაღალი ძაბვის ელექტრული განმუხტვა','Высоковольтный электрический разряд'),text('A metered spray of fuel','საწვავის დოზირებული ჭავლი','Дозированная струя топлива'),text('A continuous flow of engine coolant','გამაგრილებელი სითხის უწყვეტი ნაკადი','Непрерывный поток охлаждающей жидкости')],0,
  text('The coil supplies high voltage and the plug creates the discharge in the chamber. The injector, not the plug, meters fuel.','კოჭა მაღალ ძაბვას აწვდის, სანთელი კი კამერაში განმუხტვას ქმნის. საწვავს ფრქვევანა დოზირებს და არა სანთელი.','Катушка подаёт высокое напряжение, свеча создаёт разряд в камере. Топливо дозирует форсунка, а не свеча.'));
ask('part-spark-plug-symptom',
  text('A petrol cylinder misfires. Which evidence would justify blaming its spark plug alone?','ბენზინის ძრავის ცილინდრში წვა გამოტოვებულია. რა მტკიცებულება ამართლებს მხოლოდ სანთლის დადანაშაულებას?','В бензиновом цилиндре пропуски воспламенения. Что позволяет обвинить только свечу?'),[
    text('A misfire report alone does not isolate the plug','მხოლოდ წვის გამოტოვების შეტყობინება სანთელს ვერ გამოყოფს','Один отчёт о пропусках не выделяет свечу'),text('The cylinder number alone','მხოლოდ ცილინდრის ნომერი','Один номер цилиндра'),text('The car’s engine-family badge alone','მხოლოდ ძრავის ოჯახის აღნიშვნა','Одно обозначение семейства двигателя')],0,
  text('Misfires can involve ignition, fuel or compression. A cylinder number locates the symptom, but does not distinguish plug, coil, injector or mechanical causes.','წვის გამოტოვება აალებას, საწვავს ან შეკუმშვას უკავშირდება. ცილინდრის ნომერი სიმპტომის ადგილს გვიჩვენებს, მაგრამ სანთელს, კოჭას, ფრქვევანას ან მექანიკურ მიზეზს ვერ არჩევს.','Пропуски связаны с зажиганием, топливом или компрессией. Номер цилиндра указывает место симптома, но не отличает свечу, катушку, форсунку и механические причины.'));
ask('part-ignition-coil-function',
  text('Which sequence correctly links the controller, ignition coil and spark plug?','რომელი თანმიმდევრობა აკავშირებს სწორად კონტროლერს, აალების კოჭასა და სანთელს?','Какая последовательность верно связывает контроллер, катушку зажигания и свечу?'),[
    text('Command → high-voltage pulse → spark at the gap','ბრძანება → მაღალი ძაბვის იმპულსი → ნაპერწკალი ღრეჩოში','Команда → высоковольтный импульс → искра в зазоре'),text('Spark → stored fuel pressure → command','ნაპერწკალი → შენახული საწვავის წნევა → ბრძანება','Искра → запас давления топлива → команда'),text('High-voltage pulse → fuel spray → compression','მაღალი ძაბვის იმპულსი → საწვავის ჭავლი → შეკუმშვა','Высоковольтный импульс → распыл топлива → сжатие')],0,
  text('The controller times the coil; the coil supplies the high voltage; the plug discharges across its gap. These are connected but separate jobs.','კონტროლერი კოჭის დროს მართავს; კოჭა მაღალ ძაბვას აწვდის; სანთელი ღრეჩოში განმუხტვას ქმნის. ეს დაკავშირებული, მაგრამ სხვადასხვა სამუშაოა.','Контроллер задаёт момент работы катушки; катушка подаёт высокое напряжение; свеча создаёт разряд. Это связанные, но разные задачи.'));
ask('part-ignition-coil-symptom',
  text('In a simulator, the coil receives no electrical supply. What conclusion is justified before replacing it?','სიმულატორში კოჭას ელექტრული კვება არ მიეწოდება. რა დასკვნაა დასაბუთებული მის შეცვლამდე?','В симуляторе на катушку не поступает питание. Какой вывод обоснован до её замены?'),[
    text('The supply path must be investigated','კვების გზა გამოსაკვლევია','Нужно проверить цепь питания'),text('A new coil must restore the missing supply','ახალმა კოჭამ დაკარგული კვება აუცილებლად უნდა აღადგინოს','Новая катушка обязательно восстановит питание'),text('The spark plug must have caused the missing supply','კვების დაკარგვა აუცილებლად სანთელმა გამოიწვია','Отсутствие питания обязательно вызвано свечой')],0,
  text('The coil depends on power and control connections. Missing supply is evidence about its circuit; replacing the coil alone may leave that condition unchanged.','კოჭა კვებასა და მართვის შეერთებებზეა დამოკიდებული. დაკარგული კვება წრედის შესახებ მტკიცებულებაა; მხოლოდ კოჭის შეცვლამ შეიძლება მდგომარეობა ვერ შეცვალოს.','Катушка зависит от питания и управления. Отсутствие питания — улика о цепи; замена одной катушки может не изменить это условие.'));
ask('part-fuel-injector-function',
  text('Which distinction separates port injection from direct injection?','რომელი განსხვავება გამოყოფს პორტულ შეფრქვევას პირდაპირი შეფრქვევისგან?','Какое различие отделяет распределённый впрыск от непосредственного?'),[
    text('Spraying into the intake port versus the combustion chamber','შესხურება შემშვებ არხში ან უშუალოდ წვის კამერაში','Распыление во впускной канал либо прямо в камеру сгорания'),text('Using electricity versus using no electrical control','ელექტრობის გამოყენება ან ელექტრული მართვის არქონა','Использование электричества либо отсутствие электрического управления'),text('Using a spark plug versus a fuel rail','სანთლის ან საწვავის რეიკის გამოყენება','Использование свечи либо топливной рампы')],0,
  text('The injection location is the key distinction here. Pressure, mounting and sealing differ; similar-looking injectors are not automatically interchangeable.','აქ მთავარი განსხვავება შეფრქვევის ადგილია. წნევა, სამაგრი და დალუქვა განსხვავდება; მსგავსი ფრქვევანები ავტომატურად ურთიერთჩანაცვლებადი არ არის.','Здесь главное различие — место впрыска. Давление, крепление и уплотнение отличаются; похожие форсунки не становятся взаимозаменяемыми.'));
ask('part-fuel-injector-symptom',
  text('Several cylinders receive too little fuel and simulated rail pressure is low. What should be considered alongside individual injectors?','რამდენიმე ცილინდრს საწვავი აკლია და სიმულაციაში რეიკის წნევა დაბალია. ცალკე ფრქვევანებთან ერთად რა უნდა განვიხილოთ?','Нескольким цилиндрам не хватает топлива, давление в рампе в симуляции низкое. Что учитывать вместе с отдельными форсунками?'),[
    text('The shared fuel-supply and pressure path','საწვავის საერთო მიწოდებისა და წნევის გზა','Общий тракт подачи топлива и давления'),text('Only one cylinder’s spark-plug gap','მხოლოდ ერთი ცილინდრის სანთლის ღრეჩო','Только зазор свечи одного цилиндра'),text('Proof that every injector failed at once','მტკიცებას, რომ ყველა ფრქვევანა ერთად დაზიანდა','Доказательство одновременного отказа всех форсунок')],0,
  text('Injectors depend on supplied fuel pressure. A shared low-pressure condition can affect several cylinders; the clues do not prove every injector failed.','ფრქვევანები მიწოდებული საწვავის წნევაზეა დამოკიდებული. საერთო დაბალი წნევა რამდენიმე ცილინდრზე მოქმედებს; მინიშნებები ყველა ფრქვევანის დაზიანებას ვერ ამტკიცებს.','Форсунки зависят от подаваемого давления. Общее низкое давление может влиять на несколько цилиндров; это не доказывает отказ каждой форсунки.'));
ask('part-alternator-function',
  text('Which connection supplies the alternator’s mechanical input in a conventional belt-driven installation?','ჩვეულებრივ ღვედიან სისტემაში რომელი შეერთება აწვდის გენერატორს მექანიკურ ენერგიას?','Какая связь подводит механическую энергию к генератору в обычной ременной установке?'),[
    text('Accessory belt and pulley','დამხმარე აგრეგატების ღვედი და შკივი','Ремень вспомогательных агрегатов и шкив'),text('B+ output cable','B+ გამომავალი კაბელი','Выходной кабель B+'),text('Battery ground cable alone','მხოლოდ აკუმულატორის მასის კაბელი','Только массовый провод аккумулятора')],0,
  text('The belt drives the pulley. B+ carries electrical output; ground completes an electrical path rather than transmitting the engine’s shaft rotation.','ღვედი შკივს ამოძრავებს. B+ ელექტრულ გამომუშავებას ატარებს; მასა ელექტრულ წრედს კრავს და ძრავის ბრუნვას არ გადასცემს.','Ремень приводит шкив. B+ передаёт электрическую отдачу; масса замыкает электрическую цепь, а не передаёт вращение двигателя.'));
ask('part-alternator-symptom',
  text('A simulator shows no alternator rotation although the engine runs. What should be examined first in that evidence?','სიმულატორში ძრავა მუშაობს, მაგრამ გენერატორი არ ბრუნავს. მოცემულ მტკიცებულებაში რა უნდა შეისწავლო პირველად?','В симуляторе двигатель работает, но генератор не вращается. Что в этих данных следует проверить первым?'),[
    text('The belt and pulley drive path','ღვედისა და შკივის ამძრავის გზა','Привод через ремень и шкив'),text('Only the battery’s storage capacity','მხოლოდ აკუმულატორის ტევადობა','Только ёмкость аккумулятора'),text('Only the dashboard warning lamp','მხოლოდ დაფის გამაფრთხილებელი ნათურა','Только контрольную лампу на панели')],0,
  text('An alternator needs mechanical drive before it can generate. The stationary pulley directs attention to that path, without proving which drive component failed.','გამომუშავებისთვის გენერატორს მექანიკური ამძრავი სჭირდება. გაჩერებული შკივი ამ გზაზე მიგვითითებს, თუმცა კონკრეტული დაზიანებული ნაწილის ვინაობას არ ამტკიცებს.','Для выработки генератору нужен механический привод. Неподвижный шкив направляет внимание на этот путь, не доказывая отказ конкретной детали привода.'));
ask('part-throttle-body-function',
  text('Why does an electronic throttle report plate position back to the controller?','რატომ უბრუნებს ელექტრონული დროსელი ფირფიტის პოზიციას კონტროლერს?','Зачем электронная дроссельная заслонка сообщает контроллеру своё положение?'),[
    text('To compare actual position with the command','რეალური პოზიციის ბრძანებასთან შესადარებლად','Для сравнения фактического положения с командой'),text('To replace the actuator motor','შემსრულებელი ძრავის შესაცვლელად','Для замены исполнительного двигателя'),text('To measure exhaust temperature directly','გამონაბოლქვის ტემპერატურის პირდაპირ გასაზომად','Для прямого измерения температуры выхлопа')],0,
  text('Position feedback lets the controller check its command’s result. Commanding an opening and measuring that opening are different functions.','პოზიციის უკუკავშირით კონტროლერი ბრძანების შედეგს ამოწმებს. გახსნის ბრძანება და მისი გაზომვა სხვადასხვა ფუნქციაა.','Обратная связь положения позволяет проверить результат команды. Задать открытие и измерить его — разные функции.'));
ask('part-throttle-body-symptom',
  text('The controller commands an opening but the reported plate position does not change. Which conclusion fits the evidence?','კონტროლერი გახსნას ითხოვს, მაგრამ დაფიქსირებული პოზიცია არ იცვლება. რომელი დასკვნა შეესაბამება მტკიცებულებას?','Контроллер задаёт открытие, но сообщаемое положение не меняется. Какой вывод соответствует данным?'),[
    text('Command, actuation and feedback need comparison','ბრძანება, მოქმედება და უკუკავშირი შესადარებელია','Нужно сопоставить команду, привод и обратную связь'),text('The motor alone is definitely faulty','მხოლოდ ძრავა აუცილებლად დაზიანებულია','Точно неисправен только двигатель привода'),text('The position sensor alone is definitely faulty','მხოლოდ პოზიციის სენსორი აუცილებლად დაზიანებულია','Точно неисправен только датчик положения')],0,
  text('The plate might not move, or its reported position might be wrong. The mismatch does not yet separate mechanical, motor, wiring and feedback causes.','ფირფიტა შესაძლოა არ მოძრაობდეს, ან სიგნალი იყოს მცდარი. შეუსაბამობა ჯერ ვერ განასხვავებს მექანიკურ, ძრავის, გაყვანილობისა და უკუკავშირის მიზეზებს.','Заслонка может не двигаться либо её положение передаётся неверно. Расхождение ещё не разделяет механические причины, привод, проводку и обратную связь.'));
ask('part-brake-caliper-function',
  text('In a disc brake, which conversion takes place at the caliper?','დისკურ მუხრუჭში ენერგიისა და ძალის რომელი გარდაქმნა ხდება სუპორტში?','Какое преобразование происходит в суппорте дискового тормоза?'),[
    text('Hydraulic pressure into pad clamping force','ჰიდრავლიკური წნევა ხუნდების მოჭერის ძალად','Гидравлическое давление в усилие прижатия колодок'),text('Wheel rotation directly into electrical charge','თვლის ბრუნვა პირდაპირ ელექტრულ მუხტად','Вращение колеса напрямую в электрический заряд'),text('Pedal travel directly into tire pressure','პედლის სვლა პირდაპირ საბურავის წნევად','Ход педали напрямую в давление шины')],0,
  text('Pressure acts on the piston area to create force. The pads then create friction against the disc; regeneration is a separate energy path.','წნევა დგუშის ფართობზე მოქმედებს და ძალას ქმნის. ხუნდები დისკზე ხახუნს წარმოქმნის; რეკუპერაცია ენერგიის ცალკე გზაა.','Давление действует на площадь поршня и создаёт усилие. Колодки трутся о диск; рекуперация является отдельным путём энергии.'));
ask('part-brake-caliper-symptom',
  text('Which statement correctly compares floating and fixed calipers?','რომელი წინადადება ადარებს სწორად მცურავ და ფიქსირებულ სუპორტებს?','Какое утверждение верно сравнивает плавающий и фиксированный суппорты?'),[
    text('A floating caliper slides; a fixed caliper uses opposing pistons','მცურავი სუპორტი სრიალებს; ფიქსირებული მოპირდაპირე დგუშებს იყენებს','Плавающий суппорт перемещается; фиксированный использует встречные поршни'),text('A fixed caliper needs no pistons','ფიქსირებულ სუპორტს დგუშები არ სჭირდება','Фиксированному суппорту поршни не нужны'),text('A floating caliper brakes only one face of the disc','მცურავი სუპორტი მხოლოდ დისკის ერთ მხარეს ამუხრუჭებს','Плавающий суппорт тормозит только одной стороной диска')],0,
  text('Sliding lets a floating design apply both pads. A fixed design uses pistons on opposing sides; both clamp the disc from both faces.','სრიალი მცურავ კონსტრუქციას ორივე ხუნდის მოჭერაში ეხმარება. ფიქსირებული ტიპი მოპირდაპირე დგუშებს იყენებს; ორივე დისკს ორი მხრიდან უჭერს.','Перемещение позволяет плавающей конструкции прижимать обе колодки. Фиксированная использует поршни с двух сторон; обе конструкции зажимают обе поверхности диска.'));

ask('drivetrain-layouts-1',
  text('Which simplified power path distinguishes all-wheel drive from rear-wheel drive?','რომელი გამარტივებული ამძრავის გზა განასხვავებს სრულ ამძრავს უკანა ამძრავისგან?','Какой упрощённый путь тяги отличает полный привод от заднего?'),[
    text('A drive path reaches both front and rear axles','ამძრავის გზა წინა და უკანა ღერძებს აღწევს','Путь тяги достигает передней и задней осей'),text('The rear differential is removed from every layout','ყველა სქემიდან უკანა დიფერენციალი ამოღებულია','Во всех схемах отсутствует задний дифференциал'),text('All wheels are permanently forced to identical RPM','ყველა თვალი მუდმივად იძულებულია იდენტურ ბრუნებზე იმუშაოს','Все колёса постоянно принудительно имеют одинаковые обороты')],0,
  text('All-wheel drive can deliver drive to both axles. Exact torque distribution and hardware vary; it does not require all four wheels to rotate at one speed.','სრულ ამძრავს ორივე ღერძზე ბრუნვის გადაცემა შეუძლია. ზუსტი განაწილება და მოწყობილობა განსხვავდება; ოთხივე თვლის ერთ სიჩქარეზე ბრუნვა სავალდებულო არ არის.','Полный привод способен передавать тягу обеим осям. Распределение момента и оборудование различаются; одинаковые обороты всех четырёх колёс не обязательны.'));
ask('drivetrain-layouts-2',
  text('One F10 example is rear-wheel drive. What can you conclude about another car advertised only as “F10”?','F10-ის ერთი მაგალითი უკანაამძრავიანია. რა დასკვნა შეგიძლია გააკეთო სხვა ავტომობილზე, რომლის განცხადებაში მხოლოდ „F10“ წერია?','Один пример F10 имеет задний привод. Что можно заключить о другой машине, указанной только как «F10»?'),[
    text('Its exact model and drivetrain still need verification','მისი ზუსტი მოდელი და ამძრავი კვლავ გადასამოწმებელია','Её точную модель и привод ещё нужно проверить'),text('It must share that example’s drivetrain','მას აუცილებლად იგივე ამძრავი აქვს','У неё обязательно такой же привод'),text('Its drivetrain follows from cylinder count alone','მისი ამძრავი მხოლოდ ცილინდრების რაოდენობით დგინდება','Её привод определяется только числом цилиндров')],0,
  text('A generation code is broader than one documented configuration. Use the exact model, production details and factory information for the car being considered.','თაობის კოდი ერთ დოკუმენტირებულ ვერსიაზე ფართოა. განსახილველი ავტომობილისთვის გამოიყენე ზუსტი მოდელი, წარმოების მონაცემები და ქარხნული ინფორმაცია.','Код поколения шире одной документированной версии. Для конкретной машины используйте точную модель, данные производства и заводскую информацию.'));
ask('m-performance-0',
  text('Which pair matches the documented F10 M5 and M3 CS examples respectively?','რომელი წყვილი შეესაბამება დოკუმენტირებულ F10 M5-სა და M3 CS-ს, შესაბამისად?','Какая пара соответствует документированным F10 M5 и M3 CS соответственно?'),[
    text('S63 V8 with rear-wheel drive; inline six with M xDrive','S63 V8 უკანა ამძრავით; რიგითი ექვსცილინდრიანი M xDrive-ით','S63 V8 с задним приводом; рядная шестёрка с M xDrive'),text('Inline six with M xDrive; S63 V8 with rear-wheel drive','რიგითი ექვსცილინდრიანი M xDrive-ით; S63 V8 უკანა ამძრავით','Рядная шестёрка с M xDrive; S63 V8 с задним приводом'),text('S63 V8 with M xDrive in both examples','ორივე მაგალითში S63 V8 M xDrive-ით','В обоих примерах S63 V8 с M xDrive')],0,
  text('The two BMW releases document different engine and drivetrain combinations. The shared M name does not make their hardware identical.','BMW-ის ორი წყარო ძრავისა და ამძრავის განსხვავებულ კომბინაციებს აღწერს. საერთო M სახელი მათ მოწყობილობას იდენტურს არ ხდის.','Два материала BMW описывают разные сочетания двигателя и привода. Общее имя M не делает их оборудование одинаковым.'));
ask('m-performance-1',
  text('A seller calls a brake upgrade “M specification.” Which comparison is most useful?','გამყიდველი მუხრუჭის განახლებას „M სპეციფიკაციას“ უწოდებს. რომელი შედარებაა ყველაზე სასარგებლო?','Продавец называет улучшенные тормоза «спецификацией M». Какое сравнение полезнее всего?'),[
    text('Documented brake equipment for the exact model and package','ზუსტი მოდელისა და პაკეტის დოკუმენტირებული მუხრუჭები','Документированное тормозное оснащение точной модели и пакета'),text('Only the M logo on the caliper','მხოლოდ M ლოგო სუპორტზე','Только логотип M на суппорте'),text('Only a similar-looking M car from another generation','მხოლოდ სხვა თაობის მსგავსი გარეგნობის M ავტომობილი','Только внешне похожая M другой генерации')],0,
  text('M braking systems vary by application. Branding and appearance are weaker evidence than documentation that identifies the exact vehicle equipment.','M მუხრუჭები გამოყენების მიხედვით განსხვავდება. ბრენდინგი და გარეგნობა უფრო სუსტი მტკიცებულებაა, ვიდრე ზუსტი ავტომობილის აღჭურვილობის დოკუმენტაცია.','Тормоза M различаются по применению. Брендинг и вид слабее документации, определяющей точное оснащение автомобиля.'));
ask('m-performance-2',
  text('What does comparing the F10 M5’s rear-wheel drive with the M3 CS’s M xDrive teach?','რას გვასწავლის F10 M5-ის უკანა ამძრავისა და M3 CS-ის M xDrive-ის შედარება?','Чему учит сравнение заднего привода F10 M5 и M xDrive модели M3 CS?'),[
    text('M drivetrain configurations depend on the exact model','M-ის ამძრავი ზუსტ მოდელზეა დამოკიდებული','Конфигурация привода M зависит от точной модели'),text('Every M sedan uses the same driven axles','ყველა M სედანს იგივე წამყვანი ღერძები აქვს','У всех седанов M одинаковые ведущие оси'),text('An Active M Differential alone proves all-wheel drive','მხოლოდ Active M Differential სრულ ამძრავს ამტკიცებს','Один Active M Differential доказывает полный привод')],0,
  text('The differential and the front/rear drive layout describe different features. Check the model’s whole drivetrain instead of inferring it from one component name.','დიფერენციალი და წინა/უკანა ამძრავის სქემა სხვადასხვა თვისებაა. მთელი ამძრავი შეამოწმე და არა ერთი ნაწილის სახელით გამოიტანო დასკვნა.','Дифференциал и распределение тяги между осями — разные признаки. Проверяйте весь привод модели, а не выводите его из названия одного узла.'));
ask('checkpoint-2',
  text('An ideal 3:1 reduction receives 120 Nm at 3,000 RPM. Which output pair is correct?','იდეალურ 3:1 რედუქციას 3 000 RPM-ზე 120 Nm მიეწოდება. რომელი გამომავალი წყვილია სწორი?','На идеальное понижение 3:1 поступает 120 Nm при 3 000 RPM. Какая пара на выходе верна?'),[
    text('360 Nm at 1,000 RPM','360 Nm 1 000 RPM-ზე','360 Nm при 1 000 RPM'),text('40 Nm at 1,000 RPM','40 Nm 1 000 RPM-ზე','40 Nm при 1 000 RPM'),text('360 Nm at 9,000 RPM','360 Nm 9 000 RPM-ზე','360 Nm при 9 000 RPM')],0,
  text('Multiply torque by three and divide speed by three. An ideal reduction trades speed for torque while preserving mechanical power.','მომენტი სამზე გაამრავლე და სიჩქარე სამზე გაყავი. იდეალური რედუქცია სიჩქარეს მომენტში ცვლის და მექანიკურ სიმძლავრეს ინარჩუნებს.','Умножьте момент на три и разделите обороты на три. Идеальное понижение обменивает скорость на момент с сохранением механической мощности.'));
ask('finale-1',
  text('Which sequence keeps the turbocharger’s energy path correct?','რომელი თანმიმდევრობა აღწერს ტურბოს ენერგიის გზას სწორად?','Какая последовательность верно описывает путь энергии турбокомпрессора?'),[
    text('Exhaust → turbine → shaft → compressor','გამონაბოლქვი → ტურბინა → ლილვი → კომპრესორი','Выхлоп → турбина → вал → компрессор'),text('Intake air → turbine → exhaust → compressor','შემშვები ჰაერი → ტურბინა → გამონაბოლქვი → კომპრესორი','Впускной воздух → турбина → выхлоп → компрессор'),text('Coolant → compressor → shaft → turbine','გამაგრილებელი სითხე → კომპრესორი → ლილვი → ტურბინა','Охлаждающая жидкость → компрессор → вал → турбина')],0,
  text('Exhaust energy drives the turbine; the shaft transfers power to the compressor. The gases stay separate even though the wheels share a shaft.','გამონაბოლქვის ენერგია ტურბინას ამოძრავებს; ლილვი სიმძლავრეს კომპრესორს გადასცემს. აირები ცალ-ცალკე რჩება, მიუხედავად საერთო ლილვისა.','Энергия выхлопа приводит турбину; вал передаёт мощность компрессору. Газы остаются разделены, хотя колёса имеют общий вал.'));
ask('diagnosis-cooling-flow-0',
  text('Temperature rises at a standstill, improves with road airflow, and simulated circulation is normal. Which system best matches?','ტემპერატურა დგომისას იზრდება, გზის ჰაერით მცირდება და სიმულაციაში ცირკულაცია ნორმალურია. რომელი სისტემა ემთხვევა უკეთ?','Температура растёт на месте, снижается с дорожным обдувом, циркуляция в симуляции нормальна. Какая система подходит лучше?'),[
    text('Radiator fan and airflow control','რადიატორის ვენტილატორი და ჰაერის მართვა','Вентилятор радиатора и управление обдувом'),text('A complete loss of coolant circulation','სითხის ცირკულაციის სრული დაკარგვა','Полное отсутствие циркуляции жидкости'),text('A thermostat permanently blocking all radiator flow','თერმოსტატი, რომელიც რადიატორის მთელ ნაკადს მუდმივად კეტავს','Термостат, постоянно перекрывший весь поток радиатора')],0,
  text('The contrast follows available airflow while circulation is reported normal. This favors an airflow issue over the other listed explanations, but does not isolate one failed part.','ცვლილება ხელმისაწვდომ ჰაერს მიჰყვება, ცირკულაცია კი ნორმალურია. ეს ჩამოთვლილ ალტერნატივებზე მეტად ჰაერის პრობლემას ამყარებს, მაგრამ ერთ დაზიანებულ ნაწილს ვერ გამოყოფს.','Изменение связано с обдувом при нормальной циркуляции. Это лучше поддерживает проблему воздушного потока, чем другие варианты, но не выделяет сломанную деталь.'));
ask('diagnosis-cooling-flow-1',
  text('The simulated fan is stationary when cooling airflow is requested. Which comparison would best narrow the cause?','სიმულაციაში მოთხოვნილი გაგრილებისას ვენტილატორი გაჩერებულია. რომელი შედარება დაავიწროებს მიზეზს უკეთ?','При запросе обдува вентилятор в симуляции неподвижен. Какое сравнение лучше сузит причину?'),[
    text('Fan command, electrical supply and actual rotation','ვენტილატორის ბრძანება, კვება და რეალური ბრუნვა','Команда вентилятора, питание и фактическое вращение'),text('Only the coolant temperature warning','მხოლოდ სითხის ტემპერატურის გაფრთხილება','Только предупреждение температуры жидкости'),text('Only the radiator’s exterior size','მხოლოდ რადიატორის გარე ზომა','Только наружный размер радиатора')],0,
  text('Comparing the command with supply and response separates a control or supply issue from a fan that cannot respond. Temperature alone does not make that distinction.','ბრძანების კვებასა და რეაქციასთან შედარება მართვის ან კვების პრობლემას რეაგირების უუნარო ვენტილატორისგან არჩევს. მარტო ტემპერატურა ამას ვერ აკეთებს.','Сопоставление команды с питанием и реакцией отделяет проблему управления или питания от вентилятора, не способного ответить. Одна температура этого не различает.'));
ask('diagnosis-cooling-flow-2',
  text('New simulated evidence shows normal fan operation but a blocked air path. How should the initial idea change?','ახალი სიმულაციური მონაცემებით ვენტილატორი ნორმალურად მუშაობს, ჰაერის გზა კი დახშულია. როგორ უნდა შეიცვალოს საწყისი ვარაუდი?','Новые данные симуляции: вентилятор исправно работает, но воздушный путь перекрыт. Как пересмотреть исходную идею?'),[
    text('Investigate the obstruction rather than assume a failed fan','შეისწავლე დაბრკოლება და ნუ ჩათვლი ვენტილატორს დაზიანებულად','Исследовать препятствие, а не считать вентилятор сломанным'),text('Keep the fan-failure conclusion despite the new evidence','ახალი მტკიცებულების მიუხედავად ვენტილატორის დაზიანება დაასკვნი','Сохранить вывод об отказе вентилятора вопреки новым данным'),text('Normal fan rotation proves all cooling is normal','ვენტილატორის ნორმალური ბრუნვა მთელი გაგრილების გამართულობას ამტკიცებს','Нормальное вращение вентилятора доказывает исправность всего охлаждения')],0,
  text('Revise the explanation to fit the new evidence. A working fan cannot move enough air through an obstructed path simply because it rotates.','ახალი მტკიცებულებით ახსნა გადახედე. მბრუნავი ვენტილატორიც ვერ ატარებს საკმარის ჰაერს დახშულ გზაში.','Пересматривайте объяснение по новым данным. Даже работающий вентилятор не обеспечит достаточный воздух через перекрытый путь только потому, что вращается.'));
ask('diagnosis-boost-path-0',
  text('Requested boost is above measured pressure and a downstream charge pipe has an open gap. Which explanation is best supported?','მოთხოვნილი ბუსტი გაზომილ წნევაზე მაღალია და კომპრესორის შემდეგ მილს ღია ღრიჭო აქვს. რომელი ახსნა მყარდება უკეთ?','Запрошенный наддув выше измеренного, после компрессора в трубе есть открытая щель. Какое объяснение лучше подтверждено?'),[
    text('Compressed air escapes before the cylinders','შეკუმშული ჰაერი ცილინდრებამდე იკარგება','Сжатый воздух выходит до цилиндров'),text('The low reading must be a sensor error only','დაბალი მაჩვენებელი მხოლოდ სენსორის შეცდომაა','Низкое показание обязательно вызвано только датчиком'),text('The turbine must have stopped completely','ტურბინა აუცილებლად სრულად გაჩერდა','Турбина обязательно полностью остановилась')],0,
  text('The visible opening is direct evidence of an intake leak. The pressure reading alone would not distinguish a leak from sensor or boost-control problems.','ხილული ღრიჭო შემშვები გაჟონვის პირდაპირი მტკიცებულებაა. მარტო წნევის მაჩვენებელი გაჟონვას სენსორის ან ბუსტის მართვის პრობლემისგან ვერ განასხვავებდა.','Видимая щель прямо подтверждает утечку впуска. Одно показание давления не отличило бы её от проблем датчика или управления наддувом.'));
ask('diagnosis-boost-path-1',
  text('Which additional observation would most specifically strengthen the leak explanation in this simulator?','რომელი დამატებითი დაკვირვება გაამყარებს სიმულატორში გაჟონვის ახსნას ყველაზე კონკრეტულად?','Какое дополнительное наблюдение наиболее конкретно усилит объяснение утечки в симуляторе?'),[
    text('Air is observed escaping at the pipe gap under pressure','წნევისას ჰაერი მილის ღრიჭოდან გამოდის','Под давлением наблюдается выход воздуха через щель'),text('The dashboard repeats the low-boost warning','დაფა კვლავ დაბალი ბუსტის გაფრთხილებას აჩვენებს','Панель повторяет предупреждение о низком наддуве'),text('The car still has the same engine-family code','ავტომობილს ისევ იგივე ძრავის ოჯახის კოდი აქვს','Код семейства двигателя остался прежним')],0,
  text('A direct observation at the suspected path adds evidence about the cause. Repeating the original warning only repeats the symptom.','საეჭვო გზაზე პირდაპირი დაკვირვება მიზეზის შესახებ მტკიცებულებას ამატებს. თავდაპირველი გაფრთხილების გამეორება მხოლოდ სიმპტომს იმეორებს.','Прямое наблюдение на подозреваемом пути добавляет данные о причине. Повтор исходного предупреждения лишь повторяет симптом.'));
ask('diagnosis-boost-path-2',
  text('The simulated pipe gap is closed, but measured boost is still low. What follows?','სიმულაციაში მილის ღრიჭო დაიხურა, მაგრამ გაზომილი ბუსტი კვლავ დაბალია. რა გამომდინარეობს?','Щель в симуляции закрыта, но измеренный наддув всё ещё низкий. Что следует дальше?'),[
    text('The leak was not necessarily the only problem','გაჟონვა შესაძლოა ერთადერთი პრობლემა არ ყოფილიყო','Утечка не обязательно была единственной проблемой'),text('The original visible leak never mattered','თავდაპირველ ხილულ გაჟონვას მნიშვნელობა არასდროს ჰქონია','Исходная видимая утечка никогда не имела значения'),text('Every boost-related component must be replaced','ბუსტთან დაკავშირებული ყველა ნაწილი შესაცვლელია','Нужно заменить все детали наддува')],0,
  text('A supported cause can coexist with another fault. Use the changed evidence to continue narrowing the remaining pressure or control issue.','დასაბუთებულ მიზეზთან ერთად სხვა გაუმართაობაც შეიძლება არსებობდეს. შეცვლილი მტკიცებულებით დარჩენილი წნევის ან მართვის პრობლემა დაავიწროვე.','Подтверждённая причина может сосуществовать с другой неисправностью. Используйте новые данные, чтобы сузить оставшуюся проблему давления или управления.'));
ask('diagnosis-signal-plausibility-0',
  text('One wheel-speed trace jumps between zero and extreme values while three others and vehicle motion are smooth. What is supported?','ერთი თვლის სიგნალი ნულსა და უკიდურეს მნიშვნელობებს შორის ხტება, დანარჩენები და მოძრაობა კი გლუვია. რა მყარდება?','Сигнал одного колеса скачет от нуля до крайних значений, остальные и движение плавные. Что подтверждено?'),[
    text('An implausible signal in that measurement path','არასარწმუნო სიგნალი ამ გაზომვის გზაში','Неправдоподобный сигнал в этом измерительном тракте'),text('Proof of a failed sensor with intact wiring','დაზიანებული სენსორის მტკიცება გამართული გაყვანილობით','Доказанный отказ датчика при исправной проводке'),text('Proof that the controller is commanding those wheel speeds','მტკიცება, რომ კონტროლერი ამ ბრუნებს თავად ითხოვს','Доказательство того, что контроллер задаёт такие обороты')],0,
  text('The isolated jumps conflict with smooth motion. They identify a plausibility problem, but do not yet separate the sensor from its circuit or processing.','ცალკეული ნახტომები გლუვ მოძრაობას ეწინააღმდეგება. ეს სარწმუნოობის პრობლემაა, მაგრამ ჯერ სენსორს წრედისა და დამუშავებისგან ვერ განასხვავებს.','Изолированные скачки противоречат плавному движению. Они выявляют проблему правдоподобия, но ещё не разделяют датчик, цепь и обработку.'));
ask('diagnosis-signal-plausibility-1',
  text('Why compare the suspect wheel-speed trace with the other three traces?','რატომ უნდა შეადარო საეჭვო თვლის სიგნალი დანარჩენ სამს?','Зачем сравнивать подозрительный сигнал скорости колеса с тремя остальными?'),[
    text('They provide context for whether the change is physically plausible','ისინი აჩვენებს, რამდენად ფიზიკურად სარწმუნოა ცვლილება','Они дают контекст для физической правдоподобности изменения'),text('All four wheels must always have exactly equal RPM','ოთხივე თვალს ყოველთვის ზუსტად თანაბარი ბრუნები უნდა ჰქონდეს','Все четыре колеса всегда обязаны иметь строго равные обороты'),text('The other sensors prove their wiring can never fail','დანარჩენი სენსორები ამტკიცებს, რომ მათი გაყვანილობა ვერ დაზიანდება','Другие датчики доказывают невозможность отказа проводки')],0,
  text('Related signals help evaluate a sudden isolated jump. Wheel speeds can differ in a corner, so comparison requires context rather than demanding exact equality.','დაკავშირებული სიგნალები მოულოდნელი ნახტომის შეფასებას ეხმარება. მოსახვევში ბრუნები განსხვავდება, ამიტომ შედარებას კონტექსტი სჭირდება და არა სრული ტოლობა.','Связанные сигналы помогают оценить резкий одиночный скачок. В повороте обороты могут различаться, поэтому нужен контекст, а не требование точного равенства.'));
ask('diagnosis-signal-plausibility-2',
  text('New simulator evidence identifies an intermittent open connection in that signal path. Which conclusion is now stronger?','სიმულატორის ახალი მტკიცებულება ამ სიგნალის გზაში პერიოდულ გაწყვეტას აჩვენებს. რომელი დასკვნა მყარდება ახლა?','Новые данные симулятора выявили периодический обрыв соединения в этом тракте. Какой вывод теперь сильнее?'),[
    text('A connection fault can explain the signal dropouts','შეერთების ხარვეზი სიგნალის გაქრობას ხსნის','Неисправность соединения может объяснять пропадания сигнала'),text('The sensor itself is still the only possible cause','მაინც მხოლოდ თვითონ სენსორია შესაძლო მიზეზი','Единственной возможной причиной остаётся сам датчик'),text('The other three wheels must also have faulty sensors','დანარჩენ სამ თვალსაც დაზიანებული სენსორი უნდა ჰქონდეს','У остальных трёх колёс тоже должны быть неисправны датчики')],0,
  text('The added circuit evidence narrows the explanation. The earlier signal mismatch alone did not justify naming that connection as the cause.','დამატებითი წრედის მტკიცებულება ახსნას ავიწროებს. თავდაპირველი სიგნალის შეუსაბამობა მარტო ამ შეერთების დასახელებას ვერ ამართლებდა.','Дополнительные данные цепи сужают объяснение. Исходное расхождение сигнала само по себе не позволяло назвать именно это соединение причиной.'));

for (const code of ['N54','N55','B58','S63']) ask(code+'-variant',
  text('A replacement part lists the same engine family but a different production application. What is established?','სათადარიგო ნაწილს იგივე ძრავის ოჯახი, მაგრამ განსხვავებული წარმოების გამოყენება უწერია. რა დგინდება?','Для запчасти указано то же семейство двигателя, но другое производственное применение. Что установлено?'),[
    text('Family similarity is established; exact compatibility is not','ოჯახის მსგავსება დგინდება, ზუსტი თავსებადობა — არა','Родство семейства установлено, точная совместимость — нет'),text('The family code guarantees every connection matches','ოჯახის კოდი ყველა შეერთების დამთხვევას უზრუნველყოფს','Код семейства гарантирует совпадение всех соединений'),text('A similar exterior guarantees identical calibration','მსგავსი გარეგნობა იდენტურ კალიბრაციას უზრუნველყოფს','Похожий вид гарантирует одинаковую калибровку')],0,
  text('Shared family naming is a starting clue. Confirm the full variant, production details and application before assuming fitment or calibration compatibility.','ოჯახის საერთო სახელი საწყისი მინიშნებაა. თავსებადობისა და კალიბრაციის ვარაუდამდე დაადასტურე სრული ვერსია, წარმოების მონაცემები და გამოყენება.','Общее имя семейства — исходная подсказка. До вывода о совместимости установки или калибровки подтвердите полную версию, данные производства и применение.'));
for (const id of ['f80','g80','f10-m5']) ask('model-'+id+'-scope',
  text('The photograph identifies a generation, but a seller claims a different engine configuration. What should decide the engine identification?','ფოტო თაობას აჩვენებს, გამყიდველი კი ძრავის სხვა ვერსიას ამტკიცებს. რამ უნდა განსაზღვროს ძრავის ვინაობა?','Фото позволяет определить поколение, но продавец заявляет другую конфигурацию двигателя. Что должно определять двигатель?'),[
    text('Exact model and application documentation','ზუსტი მოდელისა და გამოყენების დოკუმენტაცია','Документация точной модели и применения'),text('The photographed grille shape alone','მხოლოდ ფოტოზე ცხაურის ფორმა','Только форма решётки на фото'),text('Another car sharing the generation code','თაობის იმავე კოდის მქონე სხვა ავტომობილი','Другая машина с тем же кодом поколения')],0,
  text('Visual recognition and engine verification answer different questions. A generation code or photograph does not establish every variant’s engine.','ვიზუალური ამოცნობა და ძრავის დადასტურება სხვადასხვა კითხვას პასუხობს. თაობის კოდი ან ფოტო ყველა ვერსიის ძრავას ვერ ადგენს.','Визуальное распознавание и проверка двигателя отвечают на разные вопросы. Код поколения или фотография не определяют двигатель каждой модификации.'));

const guide = (keyIdea,workedExample) => ({keyIdea,workedExample});
export const assessmentStudyGuides = {
  'first-engine':guide(
    text('Follow the conversion: fuel energy becomes pressure, piston movement and finally crankshaft rotation.','მიჰყევი გარდაქმნას: საწვავის ენერგია წნევად, დგუშის მოძრაობად და საბოლოოდ მუხლა ლილვის ბრუნვად იქცევა.','Проследите преобразование: энергия топлива становится давлением, движением поршня и вращением коленвала.'),
    text('Picture a bicycle pedal: a push away from the crank axis produces rotation. An engine’s connecting rod pushes an offset crank journal in a related way.','წარმოიდგინე ველოსიპედის პედალი: ღერძიდან დაშორებული ბიძგი ბრუნვას ქმნის. ძრავის ბარბაცა მსგავსად აწვება მუხლა ლილვის ექსცენტრულ ყელს.','Представьте педаль велосипеда: усилие в стороне от оси шатуна создаёт вращение. Шатун двигателя подобным образом давит на смещённую шейку коленвала.')),
  horsepower:guide(
    text('Power combines torque and rotational speed. Compare both values at a stated operating point.','სიმძლავრე მომენტსა და ბრუნვის სიხშირეს აერთიანებს. შეადარე ორივე მნიშვნელობა განსაზღვრულ რეჟიმში.','Мощность объединяет момент и частоту вращения. Сравнивайте обе величины в заданном режиме.'),
    text('At 200 Nm, doubling speed from 1,500 to 3,000 RPM doubles power at those points. It does not tell you either engine’s peak power.','200 Nm-ზე სიჩქარის 1 500-დან 3 000 RPM-მდე გაორმაგება ამ რეჟიმების სიმძლავრესაც აორმაგებს. ეს არცერთი ძრავის პიკურ სიმძლავრეს არ გვიჩვენებს.','При 200 Nm рост с 1 500 до 3 000 RPM удваивает мощность в этих точках. Это не определяет пиковую мощность двигателей.')),
  torque:guide(
    text('Turning effect depends on force and its perpendicular distance from the axis.','მაბრუნებელი ეფექტი ძალასა და ღერძიდან მის მართობულ მანძილზეა დამოკიდებული.','Вращающее действие зависит от силы и её перпендикулярного расстояния до оси.'),
    text('A 10 N perpendicular force at 0.3 m produces 3 Nm. The same force at 0.6 m produces 6 Nm. Keep force and distance units attached.','10 N მართობული ძალა 0,3 მ-ზე 3 Nm-ს ქმნის. იგივე ძალა 0,6 მ-ზე 6 Nm-ს ქმნის. ძალასა და მანძილს ერთეულები ყოველთვის მიუთითე.','Перпендикулярная сила 10 N на плече 0,3 м создаёт 3 Nm. На плече 0,6 м та же сила даёт 6 Nm. Всегда указывайте единицы силы и расстояния.')),
  rpm:guide(
    text('RPM counts revolutions per minute. It is not road speed or combustion-cycle count.','RPM წუთში ბრუნებს ითვლის. ეს არც გზის სიჩქარეა და არც წვის ციკლების რაოდენობა.','RPM считает обороты в минуту. Это не скорость автомобиля и не число циклов сгорания.'),
    text('At 600 RPM the crankshaft turns 10 times per second. One cylinder of a four-stroke engine completes five cycles in that second.','600 RPM-ზე მუხლა ლილვი წამში 10 ბრუნს ასრულებს. ოთხტაქტიანი ძრავის ერთი ცილინდრი ამ წამში ხუთ ციკლს ასრულებს.','При 600 RPM коленвал делает 10 оборотов в секунду. Один цилиндр четырёхтактного двигателя за эту секунду завершает пять циклов.')),
  transmission:guide(
    text('Reduction multiplies torque while reducing speed; it does not create power.','რედუქცია მომენტს ამრავლებს და სიჩქარეს ამცირებს; სიმძლავრეს არ ქმნის.','Понижение умножает момент, снижая обороты; мощность оно не создаёт.'),
    text('A 2:1 gearbox followed by a 3:1 final drive gives 6:1 overall reduction. Divide input RPM by six; multiply ideal input torque by six.','2:1 კოლოფი და შემდეგ 3:1 მთავარი გადაცემა ჯამში 6:1 რედუქციას იძლევა. შემავალი ბრუნები გაყავი ექვსზე; იდეალური მომენტი ექვსზე გაამრავლე.','Коробка 2:1 и главная передача 3:1 дают общее понижение 6:1. Обороты входа делите на шесть, идеальный входной момент умножайте на шесть.')),
  turbocharging:guide(
    text('The turbine and compressor share a shaft, while exhaust and intake air follow separate paths.','ტურბინასა და კომპრესორს საერთო ლილვი აქვს, გამონაბოლქვი და შემშვები ჰაერი კი ცალკე გზებს მიჰყვება.','Турбина и компрессор имеют общий вал, а выхлоп и впускной воздух идут разными путями.'),
    text('Trace two routes: exhaust manifold → turbine → exhaust; air filter → compressor → charge cooler → engine. The shared shaft transfers energy between them.','გაჰყევი ორ გზას: გამოსაშვები კოლექტორი → ტურბინა → გამონაბოლქვი; ფილტრი → კომპრესორი → ინტერკულერი → ძრავა. საერთო ლილვი მათ შორის ენერგიას გადასცემს.','Проследите два пути: выпускной коллектор → турбина → выхлоп; фильтр → компрессор → охладитель → двигатель. Общий вал передаёт между ними энергию.')),
  cooling:guide(
    text('Cooling needs both liquid circulation and heat transfer to surrounding air.','გაგრილებას სჭირდება სითხის ცირკულაციაც და გარემოს ჰაერში სითბოს გადაცემაც.','Охлаждению нужны и циркуляция жидкости, и передача тепла окружающему воздуху.'),
    text('A pump can circulate coolant while poor radiator airflow still limits heat rejection. Check the whole heat path before naming a failed component.','ტუმბო შეიძლება სითხეს ამოძრავებდეს, მაგრამ სუსტი ჰაერი რადიატორის სითბოს მოცილებას ზღუდავდეს. ნაწილის დასახელებამდე შეამოწმე სითბოს სრული გზა.','Помпа может прокачивать жидкость, а слабый обдув радиатора всё равно ограничит отвод тепла. До вывода о детали проследите весь тепловой путь.')),
  charging:guide(
    text('Generating, storing and using electrical energy are different jobs in the starting and charging system.','ელექტროენერგიის გამომუშავება, შენახვა და გამოყენება დაქოქვისა და დამუხტვის სისტემის სხვადასხვა სამუშაოა.','Выработка, хранение и использование электроэнергии — разные задачи системы запуска и зарядки.'),
    text('The starter draws stored battery energy to turn the engine. Once the engine runs, it drives the alternator, which supplies electrical power and replenishes the battery.','სტარტერი აკუმულატორის შენახული ენერგიით ძრავას ატრიალებს. მუშაობისას ძრავა გენერატორს ამოძრავებს, რომელიც ელექტროენერგიას იძლევა და აკუმულატორს ავსებს.','Стартер использует запас энергии батареи для вращения двигателя. Работающий двигатель приводит генератор, который питает электросистему и пополняет заряд.')),
  differential:guide(
    text('Driven wheels need different speeds in a corner because they travel different distances.','მოსახვევში წამყვან თვლებს სხვადასხვა სიჩქარე სჭირდება, რადგან სხვადასხვა მანძილს გადის.','В повороте ведущим колёсам нужны разные обороты, потому что они проходят разные расстояния.'),
    text('In the same turn time, the outside wheel follows a longer arc. A differential permits that wheel-speed difference while still transmitting drive.','იმავე მოხვევის დროში გარე თვალი უფრო გრძელ რკალს მიჰყვება. დიფერენციალი ამ სხვაობას ბრუნვის გადაცემისასაც უშვებს.','За то же время наружное колесо проходит более длинную дугу. Дифференциал допускает эту разницу оборотов, продолжая передавать тягу.')),
  combustion:guide(
    text('Four piston strokes complete one cycle in two crankshaft revolutions.','დგუშის ოთხი ტაქტი ერთ ციკლს მუხლა ლილვის ორ ბრუნში ასრულებს.','Четыре хода поршня завершают цикл за два оборота коленвала.'),
    text('Upward piston movement can mean compression or exhaust. The valve state distinguishes them: closed for simplified compression, exhaust valve open for exhaust.','დგუშის მაღლა მოძრაობა შეიძლება შეკუმშვასაც ნიშნავდეს და გამოშვებასაც. მათ სარქველი არჩევს: შეკუმშვისას დახურულია, გამოშვებისას გამოსაშვები ღიაა.','Подъём поршня бывает при сжатии и выпуске. Их различает состояние клапанов: при упрощённом сжатии они закрыты, при выпуске выпускной открыт.')),
  suspension:guide(
    text('Springs store motion energy; dampers dissipate it and help repeated movement settle.','ზამბარა მოძრაობის ენერგიას ინახავს; ამორტიზატორი ფანტავს და რხევის ჩაქრობას ეხმარება.','Пружины запасают энергию движения; амортизаторы рассеивают её и гасят колебания.'),
    text('After a bump the spring releases stored energy. The damper resists compression and rebound, converting motion energy into heat rather than endlessly returning it.','ბიძგის შემდეგ ზამბარა დაგროვილ ენერგიას აბრუნებს. ამორტიზატორი შეკუმშვასა და უკუსვლას ეწინააღმდეგება და ენერგიას სითბოდ აქცევს.','После неровности пружина отдаёт энергию. Амортизатор сопротивляется сжатию и отбою, превращая энергию движения в тепло, а не возвращая её бесконечно.')),
  electronics:guide(
    text('A control loop measures, compares, acts and measures again. A command is not proof of its result.','მართვის წრედი ზომავს, ადარებს, მოქმედებს და კვლავ ზომავს. ბრძანება შედეგის მტკიცებულება არ არის.','Контур управления измеряет, сравнивает, действует и измеряет снова. Команда не доказывает результат.'),
    text('An implausible wheel-speed trace identifies a measurement problem. It does not distinguish the sensor, wiring, supply or processing without more evidence.','არასარწმუნო თვლის სიგნალი გაზომვის პრობლემას ავლენს. მეტი მტკიცებულების გარეშე ის სენსორს, გაყვანილობას, კვებასა თუ დამუშავებას ვერ არჩევს.','Неправдоподобный сигнал колеса указывает на проблему измерения. Без дополнительных данных он не различает датчик, проводку, питание и обработку.')),
  electrification:guide(
    text('Regeneration reverses the energy flow, recovering some motion energy into the battery.','რეკუპერაცია ენერგიის მიმართულებას აბრუნებს და მოძრაობის ენერგიის ნაწილს აკუმულატორში აღადგენს.','Рекуперация меняет направление потока энергии, возвращая часть энергии движения в батарею.'),
    text('During propulsion, energy flows from battery to motor to wheels. During suitable deceleration, the motor generates and sends some energy back; friction brakes remain necessary.','ამძრავისას ენერგია აკუმულატორიდან ძრავის გავლით თვლებზე მიდის. შესაფერის შენელებაზე ძრავა ენერგიის ნაწილს აბრუნებს; ხახუნის მუხრუჭები მაინც საჭიროა.','При тяге энергия идёт от батареи через мотор к колёсам. При подходящем замедлении мотор генерирует и возвращает часть энергии; фрикционные тормоза остаются необходимыми.')),
};

const supplementalReferences = {
  horsepower:[{label:'NASA · power as the rate of work',url:'https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/power/'}],
  torque:[{label:'NASA · torque and perpendicular lever arm',url:'https://www.grc.nasa.gov/WWW/K-12/airplane/torque.html'}],
  transmission:[{label:'MIT · gear reduction and torque',url:'https://manipulation.csail.mit.edu/robot.html'},{label:'Northwestern · combined gear ratios',url:'https://hades.mech.northwestern.edu/index.php/Choosing_a_Motor_and_Gearing_Combination'}],
  electrification:[{label:'US DOE · hybrid drive and regeneration',url:'https://afdc.energy.gov/vehicles/how-do-hybrid-electric-cars-work'}],
};
export function applyAuthoredAssessments(lessons) {
  for (const lesson of lessons) {
    if (supplementalReferences[lesson.id]) lesson.sources.push(...supplementalReferences[lesson.id]);
    if (['torque','basics-checkpoint'].includes(lesson.id)) lesson.sources.push(...supplementalReferences.transmission.slice(0,1));
  }
  for (const lesson of lessons) lesson.questions = lesson.questions.map(question => {
    const replacement = bank.get(question.id);
    return replacement ? {...question, ...replacement, answers:[...replacement.answers]} : question;
  });
}
